import { reviewsDir } from './paths';
import { getConversation, saveConversation, saveFailureReason } from '../conversationStore';
import { createChipFromInput } from '../chipStore';
import { slugify, isSafeSegment } from '../slug';
import { atomicWrite } from '../../lib/atomicWrite';

/**
 * apply.ts — the post-approbation "git-natif" mechanics of the Banc d'essai
 * (§ 07 of the design, Lot 7). Turns an `approval` gate's answer into the
 * mechanical side effect it describes: merge + push + local install (or
 * revert), never an LLM call. See
 * `docs/plans/2026-07-23-banc-essai-evaluation-continue.html` § 07 and the
 * two named guards of § 11 (#17 beforeSha-vs-HEAD, #15 porcelain-before-pull).
 *
 * GUARD-RAIL OF THIS LOT: every git command this module or its test file
 * issues is EXECUTED ONLY against caller-supplied `remote`/`integrationClone`/
 * `installRoot`/`localClone` paths (an `ApplyContext`) — this module never
 * hardcodes `~/.claude/skills/*` or a real `claude-skills`/`meta-govern`
 * GitHub URL anywhere. Production wiring (real repo locations) is Lot 8's
 * job; until then `evals apply`/`evals revert` read those locations from
 * environment variables (see `server/cli/evals.ts`) and fail loudly if unset
 * — they never fall back to a baked-in real path.
 *
 * TWO PATHS (§ 07), dispatched on `proposal.skill === 'meta-govern'`:
 *  - Chemin A (generic skill): merge `improve/<skill>-<date>` into `main` of
 *    a monorepo-style skills repo, then COPY the skill's folder from that
 *    repo into `<installRoot>/<skill>/` (a plain, non-git directory — mirrors
 *    `~/.claude/skills/<skill>` being populated from `claude-skills`). Since
 *    `installRoot` is not itself a git working tree, "the local sha" from
 *    § 07's local guard is tracked via a small marker file written by this
 *    module (`.ws-install-sha.json` inside the installed skill folder) —
 *    there is no other way to know "has this folder diverged since
 *    `beforeSha`" without a git history to ask.
 *  - Chemin B (meta-govern): `~/.claude/skills/meta-govern` IS the local
 *    clone (not a copy target) — merge `evolve/<date>` into `main` on a
 *    SEPARATE integration clone, push, then on the LOCAL clone: guard on
 *    `git status --porcelain` (§ 11 #15), `git pull` (fast-forward only),
 *    invoke the repo's OWN `scripts/install-agent-symlinks.mjs`, then a
 *    SIMULATED mirror-resync (see `resyncMetaGovernMirror` below — pushing to
 *    a real `claude-skills` mirror is explicitly forbidden in this chantier).
 *
 * BRANCH NAMING — a documented deviation from § 07's literal wording. The
 * frozen Lot 1 `ImprovementProposal` schema has no `branch` field, so this
 * module and any future producer of a branch (the Lot 8 night judge) must
 * derive the SAME name from fields the schema DOES have. `proposalBranchName`
 * below is that single source of truth: `improve/<skill>-<YYYY-MM-DD>` (or
 * `evolve/<YYYY-MM-DD>` for meta-govern), the date read from the millisecond
 * timestamp embedded in `proposal.id` (`improvement-<ms>-<hex>`, see
 * `store.ts`'s `genId`) — deterministic, no wall-clock "today" coupling, and
 * git-ref-safe. A `-v2`/`-v3`… suffix is appended for `version > 1`.
 *
 * CHANGES_REQUESTED STATE-MACHINE NOTE — another documented deviation. § 07
 * says a `changes_requested` gate leaves "proposal.state reste proposed"
 * while also describing "une nouvelle proposal (version 2)". The frozen Lot 1
 * state graph (`store.ts`) only allows `proposed -> applied | rejected`, and
 * `createImprovementProposal` throws `DuplicateProposedProposalError` if ANY
 * `proposed` proposal already exists for that skill (exigence #12,
 * mono-proposal invariant) — so a genuinely NEW row (needed for
 * `previousProposalId` chaining, which the schema clearly intends: "Chains to
 * the previous version when `version > 1`") cannot coexist with the OLD row
 * while the old one is still `proposed`. This module resolves the tension by
 * transitioning the OLD row to `rejected` (the only terminal state that
 * fits "this exact diff will not be merged as drafted" — distinct from a
 * hard `rejected` gate answer only in that a FRESH `proposed` row
 * immediately takes its place) and creating the NEW row at `version + 1`,
 * `state: 'proposed'`, `previousProposalId` pointing at the old id. Read
 * together, the *subject* ("improve this skill") stays open exactly as § 07
 * describes, even though the specific OLD proposal row does not.
 *
 * ORDERING (finding P2, round 4) — `superviseChangesRequested` builds AND
 * durably persists the replacement's gate conversation (`saveGateConversation`)
 * FIRST, confirmed successful, before ever touching the OLD row's state. This
 * was verified NOT to be reorderable all the way down to the
 * `ImprovementProposal` write itself: store.ts's mono-proposal invariant
 * (exigence #12, `DuplicateProposedProposalError`) rejects a second
 * `'proposed'` row for the same skill unconditionally — as long as the OLD
 * row is still `proposed`, creating the NEW row throws every time, with no
 * exemption for a chained v2 (`previousProposalId` is not special-cased by
 * the store). So the NEW `ImprovementProposal` write is the one step
 * architecturally FORCED to happen AFTER the OLD row leaves `proposed` — but
 * by front-loading everything else that can plausibly fail (the git network
 * call for a fresh `beforeSha`, the gate conversation's own store write),
 * that forced step is now a single local `atomicWrite`, and its failure is
 * never swallowed: `superviseChangesRequested` opens a chip with the exact
 * manual-recovery command and re-throws, so a skill left with zero open
 * proposals is always surfaced loudly, never silent.
 *
 * RE-PROPOSAL-AFTER-REJECTION RULE (§ 07: "un refus de ta part vaut décision,
 * on n'insiste que si une évidence NOUVELLE apparaît") is a POLICY for
 * whoever drafts the NEXT proposal for a rejected skill (the Lot 8 night
 * judge, reading job findings) — this module has no access to job-finding
 * categories/severity at apply-time and does not re-implement scorecard
 * logic here. Documented as a contract for `createGatedProposal`'s callers,
 * not enforced by this module (permitted explicitly by the Lot 7 brief).
 */

/* -------------------------------------------------------------------------- */
/*  Repo targets — every git mutation is scoped to these caller-supplied      */
/*  paths; this module never bakes in a real repo location.                  */
/* -------------------------------------------------------------------------- */

interface RepoIntegrationTarget {
  /** git remote (URL or local path) for the target repo — fetchable/pushable. */
  remote: string;
  /** Scratch/integration working clone this module owns for merge+push+revert. */
  integrationClone: string;
}

/** Chemin A (generic skill improvement, § 07). */
export interface SkillRepoTarget extends RepoIntegrationTarget {
  /** Plain directory skill folders are copied into, e.g. `~/.claude/skills`. */
  installRoot: string;
}

/** Chemin B (meta-govern evolution, § 07). */
export interface MetaGovernRepoTarget extends RepoIntegrationTarget {
  /** The user's daily clone — e.g. `~/.claude/skills/meta-govern` IS this clone. */
  localClone: string;
  /** Extra env vars merged into the `install-agent-symlinks.mjs` invocation
   *  (test fixtures use this to redirect its install target; production
   *  wiring leaves it unset — the real script derives its own paths). */
  installScriptEnv?: Record<string, string>;
}

export interface ApplyContext {
  /** Required when `proposal.skill !== 'meta-govern'`. */
  skillRepo?: SkillRepoTarget;
  /** Required when `proposal.skill === 'meta-govern'`. */
  metaGovernRepo?: MetaGovernRepoTarget;
}

function resolveTarget(
  proposal: ImprovementProposal,
  ctx: ApplyContext,
): SkillRepoTarget | MetaGovernRepoTarget {
