/* -------------------------------------------------------------------------- */

function proposalDateToken(proposal: Pick<ImprovementProposal, 'id' | 'updatedAt'>): string {
  const m = /^improvement-(\d+)-/.exec(proposal.id);
  const ms = m ? Number(m[1]) : Date.parse(proposal.updatedAt);
  const date = new Date(Number.isFinite(ms) ? ms : Date.now());
  return date.toISOString().slice(0, 10);
}

/** Deterministic branch name for a git-natif proposal — see file header. */
export function proposalBranchName(
  proposal: Pick<ImprovementProposal, 'skill' | 'id' | 'version' | 'updatedAt'>,
): string {
  const date = proposalDateToken(proposal);
  const versionSuffix = proposal.version > 1 ? `-v${proposal.version}` : '';
  if (proposal.skill === 'meta-govern') {
    return `evolve/${date}${versionSuffix}`;
  }
  return `improve/${proposal.skill}-${date}${versionSuffix}`;
}

/* -------------------------------------------------------------------------- */
/*  Low-level git helpers (execFileSync — same idiom as evalsReconciler.ts /  */
/*  fixtures/makeCargoFixture.ts). Every call is scoped to a caller-supplied  */
/*  `cwd`; never a hardcoded real path.                                      */
/* -------------------------------------------------------------------------- */

/**
 * Bounded wall-clock budget for every git subprocess this module spawns
 * (finding #6, round 2 — previously NONE of them had one). These are
 * potentially NETWORK operations (clone/fetch/push against `target.remote`),
 * so deliberately more generous than a purely-LOCAL git timeout (cf.
 * `skillJobCapture.ts`'s `GIT_TIMEOUT_MS = 3_000` for local-only
 * introspection, or `gitScanner.ts`'s `5_000`) — but still bounded: a
 * hung/unresponsive git must never be able to hold the dedicated
