1139	}
1140	
1141	export interface CreateGatedProposalInput {
1142	  skill: string;
1143	  fromJobs: string[];
1144	  beforeSha: string;
1145	  diffPath: string;
1146	  backupPath: string;
1147	  /** 1 by default; pass `previousProposalId`'s caller-computed `version + 1` for a re-draft. */
1148	  version?: number;
