1150	  /** Human-readable summary of the jobs/findings that justify the proposal. */
1151	  jobsSummary: string;
1152	  /** Readable diff text — plain text is enough per the brief (no HTML needed). */
1153	  diffText: string;
1154	  /** Expected effect, human-readable (DoG movement, grade band, …). */
1155	  expectedEffect: string;
