1167	/**
1168	 * Builds and durably persists ONLY the `approval` gate conversation for a
1169	 * proposal-to-be (id/branch/gateId derivation + the `saveConversation`
1170	 * write) — no `ImprovementProposal` row is touched here. Extracted out of
1171	 * `createGatedProposal` (finding P2, round 4 — see `superviseChangesRequested`
1172	 * below) so a caller that needs the ImprovementProposal write to land as
1173	 * LATE, and as minimally, as possible can run every genuinely fallible step
1174	 * here FIRST, in isolation, before anything else is mutated.
1175	 * `createGatedProposal` itself is just this immediately followed by
1176	 * `createImprovementProposal` — its own external behavior is unchanged by
1177	 * this split.
1178	 */
1179	async function saveGateConversation(
1180	  input: CreateGatedProposalInput,
1181	): Promise<SavedGateConversation> {
1182	  const id = genImprovementId();
1183	  const version = input.version ?? 1;
1184	  const now = new Date().toISOString();
1185	  const branch = proposalBranchName({ skill: input.skill, id, version, updatedAt: now });
1186	
1187	  const gateId =
1188	    `${now.slice(0, 10)}-gate-${slugify(input.skill)}` +
1189	    `${version > 1 ? `-v${version}` : ''}-${crypto.randomBytes(3).toString('hex')}`;
1190	
1191	  const contextLines = [
1192	    `Skill : ${input.skill}`,
1193	    `Jobs sources (fromJobs) : ${input.fromJobs.join(', ')}`,
1194	    input.jobsSummary,
1195	    '',
1196	    `Branche : ${branch}`,
1197	    `Effet attendu : ${input.expectedEffect}`,
1198	    input.supersedesNote ? `Fait suite à : ${input.supersedesNote}` : undefined,
1199	    '',
1200	    'Diff :',
1201	    input.diffText,
1202	  ].filter((l): l is string => l !== undefined);
1203	
1204	  const conversationBody: Conversation = {
1205	    schemaVersion: 1,
1206	    id: gateId,
1207	    project: { slug: GATE_PROJECT_SLUG, name: GATE_PROJECT_NAME },
1208	    title: `Amélioration proposée — ${input.skill}${version > 1 ? ` (v${version})` : ''}`,
1209	    status: 'pending',
1210	    items: [
1211	      {
1212	        id: 'gate',
1213	        kind: 'approval',
1214	        prompt: `Approuver l'amélioration proposée pour le skill « ${input.skill} » ?`,
1215	        context: contextLines.join('\n'),
1216	        allowChanges: true,
1217	        status: 'pending',
1218	      },
1219	    ],
1220	    createdAt: now,
1221	    updatedAt: now,
1222	    createdBy: 'claude',
1223	  };
1224	
1225	  const saveResult = await saveConversation(GATE_PROJECT_SLUG, gateId, conversationBody);
1226	  if (!saveResult.ok) {
1227	    throw new Error(`Échec de création de la gate ${gateId} : ${saveFailureReason(saveResult)}`);
1228	  }
1229	
1230	  const gateRef = `${GATE_PROJECT_SLUG}/${gateId}`;
1231	  return { id, gateId, gateRef, branch };
1232	}
1233	
1234	/**
1235	 * Creates the `approval` gate conversation AND its linked `ImprovementProposal`
1236	 * together (§ 07: "créée à l'import du matin, en même temps que
1237	 * l'ImprovementProposal qui la référence"). The gate's `context` carries
1238	 * everything a phone-reading approver needs: jobs sources, branch name, a
1239	 * readable diff, and the expected effect. Never writes a `response` — this
1240	 * module only ever READS a gate's answer (`readGateApproval`), preserving
1241	 * the identity guard's invariant that the agent path never answers its own
1242	 * gate.
1243	 */
1244	export async function createGatedProposal(
1245	  input: CreateGatedProposalInput,
1246	): Promise<{ proposal: ImprovementProposal; branch: string; gateRef: string }> {
1247	  const { id, gateRef, branch } = await saveGateConversation(input);
1248	
1249	  const proposal = await createImprovementProposal({
