 *  reviewed entity is a SKILL, not a `~/Desktop/my-projets/<name>` project,
 *  so gates are self-referentially filed under the workstation project
 *  itself (matches the `gateRef` doc comment in `src/types/review.ts`:
 *  `'workstation/<convId>'`). */
export const GATE_PROJECT_SLUG = 'workstation';
const GATE_PROJECT_NAME = 'Workstation';

function genImprovementId(): string {
  return `improvement-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;
}

export interface CreateGatedProposalInput {
  skill: string;
  fromJobs: string[];
  beforeSha: string;
  diffPath: string;
  backupPath: string;
  /** 1 by default; pass `previousProposalId`'s caller-computed `version + 1` for a re-draft. */
  version?: number;
  previousProposalId?: string;
  /** Human-readable summary of the jobs/findings that justify the proposal. */
  jobsSummary: string;
  /** Readable diff text — plain text is enough per the brief (no HTML needed). */
  diffText: string;
  /** Expected effect, human-readable (DoG movement, grade band, …). */
  expectedEffect: string;
  /** Free-text pointer back to a superseded gate/proposal (changes_requested re-draft only). */
  supersedesNote?: string;
}

interface SavedGateConversation {
  id: string;
  gateId: string;
  gateRef: string;
  branch: string;
}

/**
 * Builds and durably persists ONLY the `approval` gate conversation for a
 * proposal-to-be (id/branch/gateId derivation + the `saveConversation`
 * write) — no `ImprovementProposal` row is touched here. Extracted out of
 * `createGatedProposal` (finding P2, round 4 — see `superviseChangesRequested`
 * below) so a caller that needs the ImprovementProposal write to land as
 * LATE, and as minimally, as possible can run every genuinely fallible step
 * here FIRST, in isolation, before anything else is mutated.
 * `createGatedProposal` itself is just this immediately followed by
 * `createImprovementProposal` — its own external behavior is unchanged by
 * this split.
 */
async function saveGateConversation(
  input: CreateGatedProposalInput,
): Promise<SavedGateConversation> {
  const id = genImprovementId();
  const version = input.version ?? 1;
  const now = new Date().toISOString();
  const branch = proposalBranchName({ skill: input.skill, id, version, updatedAt: now });

  const gateId =
    `${now.slice(0, 10)}-gate-${slugify(input.skill)}` +
    `${version > 1 ? `-v${version}` : ''}-${crypto.randomBytes(3).toString('hex')}`;

  const contextLines = [
    `Skill : ${input.skill}`,
    `Jobs sources (fromJobs) : ${input.fromJobs.join(', ')}`,
    input.jobsSummary,
    '',
    `Branche : ${branch}`,
    `Effet attendu : ${input.expectedEffect}`,
    input.supersedesNote ? `Fait suite à : ${input.supersedesNote}` : undefined,
    '',
    'Diff :',
    input.diffText,
  ].filter((l): l is string => l !== undefined);

  const conversationBody: Conversation = {
    schemaVersion: 1,
    id: gateId,
    project: { slug: GATE_PROJECT_SLUG, name: GATE_PROJECT_NAME },
    title: `Amélioration proposée — ${input.skill}${version > 1 ? ` (v${version})` : ''}`,
    status: 'pending',
    items: [
      {
        id: 'gate',
        kind: 'approval',
        prompt: `Approuver l'amélioration proposée pour le skill « ${input.skill} » ?`,
        context: contextLines.join('\n'),
        allowChanges: true,
        status: 'pending',
      },
    ],
    createdAt: now,
    updatedAt: now,
    createdBy: 'claude',
  };

  const saveResult = await saveConversation(GATE_PROJECT_SLUG, gateId, conversationBody);
  if (!saveResult.ok) {
    throw new Error(`Échec de création de la gate ${gateId} : ${saveFailureReason(saveResult)}`);
  }

  const gateRef = `${GATE_PROJECT_SLUG}/${gateId}`;
  return { id, gateId, gateRef, branch };
}

/**
 * Creates the `approval` gate conversation AND its linked `ImprovementProposal`
 * together (§ 07: "créée à l'import du matin, en même temps que
 * l'ImprovementProposal qui la référence"). The gate's `context` carries
 * everything a phone-reading approver needs: jobs sources, branch name, a
 * readable diff, and the expected effect. Never writes a `response` — this
 * module only ever READS a gate's answer (`readGateApproval`), preserving
 * the identity guard's invariant that the agent path never answers its own
 * gate.
 */
export async function createGatedProposal(
  input: CreateGatedProposalInput,
): Promise<{ proposal: ImprovementProposal; branch: string; gateRef: string }> {
  const { id, gateRef, branch } = await saveGateConversation(input);

  const proposal = await createImprovementProposal({
    id,
    skill: input.skill,
    fromJobs: input.fromJobs,
    beforeSha: input.beforeSha,
    diffPath: input.diffPath,
    backupPath: input.backupPath,
    gateRef,
    version: input.version ?? 1,
    previousProposalId: input.previousProposalId,
  });

