731	
732	/**
733	 * Builds the `ApplyContext` from environment variables — NEVER a hardcoded
734	 * default pointing at a real `~/.claude/skills/*` path (see apply.ts's file
735	 * header and the Lot 7 guard-rail). A target is only populated when ALL of
736	 * its required env vars are set; `applyProposal`/`revertProposal` then throw
737	 * a clear error if the proposal's skill needs a target that is missing.
738	 */
739	function applyContextFromEnv(): ApplyContext {
740	  const ctx: ApplyContext = {};
741	
742	  const skillsRemote = process.env.WORKSTATION_SKILLS_REPO_REMOTE;
743	  const skillsIntegrationClone = process.env.WORKSTATION_SKILLS_INTEGRATION_CLONE;
744	  const skillsInstallRoot = process.env.WORKSTATION_SKILLS_INSTALL_ROOT;
745	  if (skillsRemote && skillsIntegrationClone && skillsInstallRoot) {
746	    ctx.skillRepo = {
747	      remote: skillsRemote,
748	      integrationClone: skillsIntegrationClone,
749	      installRoot: skillsInstallRoot,
750	    };
751	  }
752	
753	  const metaGovernRemote = process.env.WORKSTATION_METAGOVERN_REPO_REMOTE;
754	  const metaGovernIntegrationClone = process.env.WORKSTATION_METAGOVERN_INTEGRATION_CLONE;
755	  const metaGovernLocalClone = process.env.WORKSTATION_METAGOVERN_LOCAL_CLONE;
756	  if (metaGovernRemote && metaGovernIntegrationClone && metaGovernLocalClone) {
757	    ctx.metaGovernRepo = {
758	      remote: metaGovernRemote,
759	      integrationClone: metaGovernIntegrationClone,
760	      localClone: metaGovernLocalClone,
761	    };
762	  }
763	
764	  return ctx;
765	}
766	
767	async function cmdApply(proposalId: string) {
768	  const outcome = await applyProposal(proposalId, applyContextFromEnv());
769	  switch (outcome.kind) {
770	    case 'pending':
771	      process.stdout.write(
772	        `VERDICT: PENDING\nGate ${outcome.proposal.gateRef} n'a pas encore de réponse — rien n'a bougé.\n`,
773	      );
774	      break;
775	    case 'rejected':
776	      process.stdout.write(
777	        `VERDICT: REJECTED\nProposal ${outcome.proposal.id} rejetée — branche supprimée, main intact, rien installé.\n`,
778	      );
779	      break;
780	    case 'changes_requested':
781	      process.stdout.write(
782	        `VERDICT: CHANGES_REQUESTED\nAncienne proposal ${outcome.proposal.id} close — nouvelle proposal ` +
783	          `${outcome.supersededBy.id} (v${outcome.supersededBy.version}) créée, gate ${outcome.newGateRef}.\n`,
784	      );
785	      break;
786	    case 'rebase_needed':
787	      process.stdout.write(
788	        `VERDICT: REBASE_NEEDED\n${outcome.reason}\nChip ouvert : ${outcome.chip.id}\n`,
789	      );
790	      break;
791	    case 'applied':
792	      process.stdout.write(
793	        `VERDICT: APPLIED\nProposal ${outcome.proposal.id} appliquée — mergeSha ${outcome.proposal.mergeSha}\n`,
794	      );
795	      break;
796	  }
797	}
798	
799	async function cmdRevert(proposalId: string) {
800	  const outcome = await revertProposal(proposalId, applyContextFromEnv());
801	  if (outcome.kind === 'rebase_needed') {
802	    process.stdout.write(
803	      `VERDICT: REBASE_NEEDED\n${outcome.reason}\nChip ouvert : ${outcome.chip.id}\n`,
804	    );
805	    return;
806	  }
807	  process.stdout.write(`VERDICT: REVERTED\nProposal ${outcome.proposal.id} revert effectué.\n`);
808	}
809	
810	/**
811	 * `evals rebase-refresh <proposalId>` — the CLI wiring `refreshBeforeSha`'s
812	 * own docstring (server/services/reviews/apply.ts) points to: the ONLY
813	 * legitimate way to unstick a proposal permanently wedged in `rebase_needed`
814	 * by the §11 #17 guard (beforeSha vs the target's real HEAD). Meant to be run
815	 * AFTER a human has confirmed the proposal's branch is still valid despite
816	 * the divergence (the chip a `rebase_needed` outcome opens spells this out) —
