 * header and the Lot 7 guard-rail). A target is only populated when ALL of
 * its required env vars are set; `applyProposal`/`revertProposal` then throw
 * a clear error if the proposal's skill needs a target that is missing.
 */
function applyContextFromEnv(): ApplyContext {
  const ctx: ApplyContext = {};

  const skillsRemote = process.env.WORKSTATION_SKILLS_REPO_REMOTE;
  const skillsIntegrationClone = process.env.WORKSTATION_SKILLS_INTEGRATION_CLONE;
  const skillsInstallRoot = process.env.WORKSTATION_SKILLS_INSTALL_ROOT;
  if (skillsRemote && skillsIntegrationClone && skillsInstallRoot) {
    ctx.skillRepo = {
      remote: skillsRemote,
      integrationClone: skillsIntegrationClone,
      installRoot: skillsInstallRoot,
    };
  }

  const metaGovernRemote = process.env.WORKSTATION_METAGOVERN_REPO_REMOTE;
  const metaGovernIntegrationClone = process.env.WORKSTATION_METAGOVERN_INTEGRATION_CLONE;
  const metaGovernLocalClone = process.env.WORKSTATION_METAGOVERN_LOCAL_CLONE;
  if (metaGovernRemote && metaGovernIntegrationClone && metaGovernLocalClone) {
    ctx.metaGovernRepo = {
      remote: metaGovernRemote,
      integrationClone: metaGovernIntegrationClone,
      localClone: metaGovernLocalClone,
    };
  }

  return ctx;
}

async function cmdApply(proposalId: string) {
  const outcome = await applyProposal(proposalId, applyContextFromEnv());
  switch (outcome.kind) {
    case 'pending':
