function flagValue(args: string[], flag: string): string | undefined {
  const idx = args.indexOf(flag);
  return idx !== -1 ? args[idx + 1] : undefined;
}

const SUBCOMMANDS =
  'pending | jobs | stamp | config | report | digest | ingest-incoming | export | import | audit-cargo | purge | judge-local | apply | revert | rebase-refresh';

const USAGE: Record<string, string> = {
  pending: 'evals pending',
  jobs: 'evals jobs [--state <état>]',
  stamp: 'evals stamp <sessionId> <état> [--runtime <r>] [--project <slug>] [--tier <tier>]',
  config: 'evals config get [<clé.pointée>]  |  evals config set <clé.pointée> <valeur>',
  report: 'evals report',
  digest: 'evals digest <jobId>',
  'ingest-incoming': 'evals ingest-incoming [--from <dir>]',
  export: 'evals export [--dry-run]',
  import: 'evals import [--dry-run] [--date <AAAA-MM-JJ>] --from <chemin>',
  'audit-cargo': 'evals audit-cargo <branche> [--from <chemin>]',
  purge: 'evals purge [--from <chemin>]',
  'judge-local': 'evals judge-local [--dry-run] [--force]',
  apply: 'evals apply <proposalId>',
  revert: 'evals revert <proposalId>',
  'rebase-refresh': 'evals rebase-refresh <proposalId>',
};

/** Forwarded (Lot 6, +`judge-local` Lot 3 du chantier "Juge local")
 *  subcommands — implemented in evalsReconciler.ts, kept as a standalone CLI
 *  (see its own header) so it stays directly invocable by the
 *  LaunchAgents/00bis task entries without going through this dispatcher.
 *  `evals <cmd>` just relays argv/stdio/exit code, no logic duplicated here. */
const RECONCILER_COMMANDS = new Set(['export', 'import', 'audit-cargo', 'purge', 'judge-local']);

function forwardToReconciler(cmd: string, rest: string[]): never {
  const child = Bun.spawnSync(['bun', path.join(import.meta.dir, 'evalsReconciler.ts'), cmd, ...rest], {
    stdout: 'inherit',
    stderr: 'inherit',
    stdin: 'inherit',
    env: process.env,
  });
  process.exit(child.exitCode ?? 1);
}

async function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  if (isHelpRequest(cmd)) {
    printUsage('evals', SUBCOMMANDS);
    return;
  }
  if (subcommandHelp(cmd, rest, USAGE)) return;

  if (cmd !== undefined && RECONCILER_COMMANDS.has(cmd)) {
    forwardToReconciler(cmd, rest);
  }

  switch (cmd) {
    case 'pending':
      await cmdPending();
      break;
    case 'jobs':
      await cmdJobs(flagValue(rest, '--state'));
      break;
    case 'stamp':
      if (rest.length < 2) fail(`usage: ${USAGE.stamp}`);
      await cmdStamp(rest[0], rest[1], {
        runtime: flagValue(rest, '--runtime'),
        project: flagValue(rest, '--project'),
        tier: flagValue(rest, '--tier'),
      });
      break;

