/*  Low-level git helpers (execFileSync — same idiom as evalsReconciler.ts /  */
/*  fixtures/makeCargoFixture.ts). Every call is scoped to a caller-supplied  */
/*  `cwd`; never a hardcoded real path.                                      */
/* -------------------------------------------------------------------------- */

/**
 * Bounded wall-clock budget for every git subprocess this module spawns
 * (finding #6, round 2 — previously NONE of them had one). These are
 * potentially NETWORK operations (clone/fetch/push against `target.remote`),
 * so deliberately more generous than a purely-LOCAL git timeout (cf.
 * `skillJobCapture.ts`'s `GIT_TIMEOUT_MS = 3_000` for local-only
 * introspection, or `gitScanner.ts`'s `5_000`) — but still bounded: a
 * hung/unresponsive git must never be able to hold the dedicated
 * `evals-apply.lock` past its own staleness window unnoticed. `killSignal:
 * 'SIGKILL'` (not the default SIGTERM) matches the finding's explicit ask —
 * a stuck git process should not be given a chance to ignore the signal.
 */
// NOTE: also reused (not just by git calls) for `runInstallAgentSymlinks`'s
// `execFileSync('node', ...)` below (finding #1, round 3) — see that call
// site's comment. Kept under this name rather than introducing a second
// constant: both bound a subprocess spawned while `evals-apply.lock` is
// held, and 60s is an equally reasonable local ceiling for a symlink-install
// script as it is for a network git operation.
const GIT_TIMEOUT_MS = 60_000;

function git(args: string[], cwd: string): void {
  execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'ignore', 'ignore'],
    timeout: GIT_TIMEOUT_MS,
    killSignal: 'SIGKILL',
  });
}

function gitOut(args: string[], cwd: string): string {
  return execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
    timeout: GIT_TIMEOUT_MS,
    killSignal: 'SIGKILL',
  }).trim();
}

function gitRevParseOrUndefined(ref: string, cwd: string): string | undefined {
  try {
    return gitOut(['rev-parse', ref], cwd);
  } catch {
    return undefined;
  }
}

interface GitTryResult {
  ok: boolean;
  stdout: string;
  stderr: string;
}

/**
 * Runs git WITHOUT throwing on a non-zero exit — captures stdout+stderr so
 * a caller can inspect *why* it failed (idempotent-revert detection in
 * `revertMergeCommitOnMain`, merge-conflict messaging in
 * `mergeApprovedBranchIntoMain`/`pullInstallAndResyncMetaGovern`) instead of
 * only getting a generic thrown Error. Same timeout/killSignal discipline as
 * `git`/`gitOut` above.
 */
function gitTry(args: string[], cwd: string): GitTryResult {
  try {
    const stdout = execFileSync('git', args, {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: GIT_TIMEOUT_MS,
      killSignal: 'SIGKILL',
    });
    return { ok: true, stdout, stderr: '' };
  } catch (err) {
    const e = err as { stdout?: string; stderr?: string };
    return { ok: false, stdout: e.stdout ?? '', stderr: e.stderr ?? '' };

