100	/**
101	 * Parses `git ls-remote --heads <remote> <branch>` output. Empty stdout means
102	 * the branch does not exist on that remote (git exits 0 either way — a
103	 * missing ref is NOT an error for `ls-remote`, unlike `fetch`).
104	 */
105	function parseLsRemoteHeadSha(stdout: string): string | undefined {
106	  const line = stdout
107	    .split('\n')
108	    .map((l) => l.trim())
109	    .find((l) => l.length > 0);
110	  if (!line) return undefined;
111	  const sha = line.split(/\s+/, 1)[0];
112	  return sha || undefined;
