 * free to swap this for a reused clone if profiling ever shows it matters.
 *
 * GIT TIMEOUT IDIOM — duplicated verbatim from `apply.ts` (`GIT_TIMEOUT_MS`,
 * `git`/`gitOut`/`gitTry` — see that file's own comment on the constant, ~L238
 * -320), not re-imported: `apply.ts` does not export these helpers, and the
 * task brief is explicit that this module must reuse the SAME timeout value,
 * not invent a different one. Every git subprocess this module spawns is
 * bounded by `GIT_TIMEOUT_MS` with `killSignal: 'SIGKILL'`, exactly like
 * `apply.ts`.
 */

/** Same value as `apply.ts`'s `GIT_TIMEOUT_MS` — see that file's docstring on
 *  the constant. Duplicated deliberately (not re-imported: `apply.ts` does
 *  not export it), per the task brief's explicit instruction to reuse the
 *  same value rather than invent a new one. */
const GIT_TIMEOUT_MS = 60_000;

function git(args: string[], cwd: string): void {
  execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'ignore', 'ignore'],
    timeout: GIT_TIMEOUT_MS,
    killSignal: 'SIGKILL',
  });
}

function gitOut(args: string[], cwd: string): string {
  return execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
    timeout: GIT_TIMEOUT_MS,
    killSignal: 'SIGKILL',
  }).trim();
}

interface GitTryResult {
  ok: boolean;
  stdout: string;
  stderr: string;
}

/** Runs git WITHOUT throwing on a non-zero exit — same contract as
 *  `apply.ts`'s own `gitTry` (captures stdout+stderr for a typed failure
 *  reason instead of a generic thrown Error). */
function gitTry(args: string[], cwd: string): GitTryResult {
  try {
    const stdout = execFileSync('git', args, {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: GIT_TIMEOUT_MS,
      killSignal: 'SIGKILL',
    });
    return { ok: true, stdout, stderr: '' };
  } catch (err) {
    const e = err as { stdout?: string; stderr?: string };
    return { ok: false, stdout: e.stdout ?? '', stderr: e.stderr ?? '' };
  }
}

/**
 * Parses `git ls-remote --heads <remote> <branch>` output. Empty stdout means
 * the branch does not exist on that remote (git exits 0 either way — a
 * missing ref is NOT an error for `ls-remote`, unlike `fetch`).
 */
function parseLsRemoteHeadSha(stdout: string): string | undefined {
  const line = stdout
    .split('\n')
    .map((l) => l.trim())
    .find((l) => l.length > 0);
  if (!line) return undefined;
  const sha = line.split(/\s+/, 1)[0];
  return sha || undefined;
}

/* -------------------------------------------------------------------------- */
/*  Branch-name guard-rail                                                    */
/* -------------------------------------------------------------------------- */

/** Refs this module is EVER allowed to touch on the destination remote — a
 *  `improve/<skill>-<date>` (generic skill, Chemin A of `apply.ts`) or
 *  `evolve/<date>` (meta-govern, Chemin B). Enforced by the module itself
 *  (not just documented convention): `transportImproveBranch` returns
 *  `rejected-branch-name` and issues ZERO git subprocess calls (fetch or
 *  push) whenever this fails. */
const ALLOWED_BRANCH_PREFIXES = ['improve/', 'evolve/'];

/** A conservative git-ref-safety check beyond the prefix allow-list: no
 *  whitespace, no `:` (would corrupt the `src:dst` refspec strings this
 *  module builds), no `..` (git itself rejects this in a ref name, but
 *  failing fast here keeps the reason message specific to THIS module),
 *  and it must not end in `/` (git also rejects that, same rationale). */
function isSafeBranchRef(branch: string): boolean {
  if (branch.length === 0) return false;
  if (/\s/.test(branch)) return false;
  if (branch.includes(':')) return false;
  if (branch.includes('..')) return false;
  if (branch.endsWith('/')) return false;
  if (branch.startsWith('-')) return false;
  return true;
}

function rejectionReasonForBranch(branch: string): string | undefined {
  const hasAllowedPrefix = ALLOWED_BRANCH_PREFIXES.some((p) => branch.startsWith(p));
  if (!hasAllowedPrefix) {
    return (
      `branche refusée : ${JSON.stringify(branch)} ne commence pas par ` +
      `${ALLOWED_BRANCH_PREFIXES.map((p) => JSON.stringify(p)).join(' ni ')} — ce module ne ` +
      'transporte jamais autre chose qu\'une branche improve/*|evolve/* du Banc d\'essai'
    );
  }
  if (!isSafeBranchRef(branch)) {
    return `branche refusée : ${JSON.stringify(branch)} n'est pas une référence git sûre (espace, ':', '..', '/' final, ou '-' initial)`;
  }
  return undefined;
}

/* -------------------------------------------------------------------------- */
/*  Public API                                                                */
/* -------------------------------------------------------------------------- */

export interface TransportImproveBranchInput {
  /** Remote (URL or local path) the branch is fetched FROM — the CARGO
   *  remote in production. Never hardcoded by this module; always supplied
   *  by the caller. */
  cargoRemote: string;
  /** Remote (URL or local path) the branch is pushed TO — the real skills
   *  repo (`claude-skills`) in production. Never hardcoded by this module;
   *  always supplied by the caller. */
  destinationRemote: string;
  /** Full branch name, e.g. `improve/<skill>-<date>` or `evolve/<date>`.
   *  Validated by this function BEFORE any git subprocess is spawned — see
   *  `rejectionReasonForBranch`. */
  branch: string;
}

export type TransportImproveBranchResult =
  /** Branch fetched from `cargoRemote` and pushed to `destinationRemote`
   *  under the same name (no `--force`, ever). */
  | { ok: true; kind: 'pushed'; branch: string; sha: string }
  /** IDEMPOTENT short-circuit: `destinationRemote` already carries `branch`
   *  at the exact same sha the cargo has — nothing was pushed. */
  | { ok: true; kind: 'already-up-to-date'; branch: string; sha: string }
  /** `branch` does not exist on `cargoRemote` at all. */
  | { ok: false; kind: 'source-branch-missing'; branch: string; reason: string }
  /** `branch` does not start with `improve/`/`evolve/`, or is not a safe git
   *  ref — rejected before any git subprocess ran. */
  | { ok: false; kind: 'rejected-branch-name'; branch: string; reason: string }
  /** `destinationRemote` already carries `branch` at a DIFFERENT sha and the
   *  push was rejected as a non-fast-forward (this module never retries with
   *  `--force`). */
  | { ok: false; kind: 'push-rejected'; branch: string; reason: string };

/**
 * Re-pushes `branch` from `cargoRemote` to `destinationRemote`, unchanged,
 * under the same name. See the file header for the full rationale
 * (idempotence, temporary-clone choice, timeout idiom, branch-name
 * guard-rail).
 *
 * Guard-rails (enforced by this function itself, not just documented):
 *  - `branch` must start with `improve/` or `evolve/` and be a safe git
 *    ref — checked FIRST, before any git subprocess call (fetch OR push).
 *  - never `--force` on any push, under any circumstance.
 *  - every git subprocess is bounded by `GIT_TIMEOUT_MS` (60s, `SIGKILL` on
 *    timeout) — same idiom, same value, as `apply.ts`.
 *  - idempotent: if `destinationRemote` already has `branch` at the same sha
 *    as `cargoRemote`, nothing is pushed — the result says so explicitly
 *    (`kind: 'already-up-to-date'`), it is not just a log line.
 */
export async function transportImproveBranch(
  input: TransportImproveBranchInput,
): Promise<TransportImproveBranchResult> {
  const { cargoRemote, destinationRemote, branch } = input;

  const rejectionReason = rejectionReasonForBranch(branch);
  if (rejectionReason !== undefined) {
    return { ok: false, kind: 'rejected-branch-name', branch, reason: rejectionReason };
  }

  const scratch = await mkdtemp(path.join(os.tmpdir(), 'ws-improve-transport-'));
  try {
    // A plain (non-bare) empty repo is enough — this module only ever needs
    // to hold ONE fetched ref long enough to push it elsewhere; it never
    // checks anything out.
    git(['init', '-q', scratch], scratch);
    git(['config', 'user.email', 'workstation-evals@local'], scratch);
    git(['config', 'user.name', 'workstation-evals'], scratch);

    // Fetch ONLY `branch` from the cargo remote, into a same-named local ref
    // — a missing branch makes `git fetch` exit non-zero (unlike
    // `ls-remote`), so `gitTry` here doubles as the existence check.
    const fetchResult = gitTry(
      ['fetch', '-q', cargoRemote, `${branch}:refs/heads/${branch}`],
      scratch,
    );
    if (!fetchResult.ok) {
      return {
        ok: false,
        kind: 'source-branch-missing',
        branch,
        reason:
          `branche ${branch} introuvable sur le remote cargo ${cargoRemote} : ` +
          (fetchResult.stderr || fetchResult.stdout || 'sortie vide'),
      };
    }
    const sourceSha = gitOut(['rev-parse', `refs/heads/${branch}`], scratch);

    // Idempotence check — ask the DESTINATION remote directly (no clone of
    // it needed) whether it already carries this branch, and at what sha.
    const lsRemoteOut = gitOut(['ls-remote', '--heads', destinationRemote, branch], scratch);
    const destinationSha = parseLsRemoteHeadSha(lsRemoteOut);

    if (destinationSha === sourceSha) {
      return { ok: true, kind: 'already-up-to-date', branch, sha: sourceSha };
    }

    // Never `--force`: if the destination already has `branch` at a
    // DIFFERENT sha, a plain push is only accepted when it fast-forwards.
    // Anything else (destination diverged, or already up to date content-
    // wise but git still refuses for ref-log reasons) comes back as a typed
    // `push-rejected` failure instead of silently rewriting history there.
    const pushResult = gitTry(
      ['push', destinationRemote, `refs/heads/${branch}:refs/heads/${branch}`],
      scratch,
    );
    if (!pushResult.ok) {
      return {
        ok: false,
        kind: 'push-rejected',
        branch,
        reason:
          `push de ${branch} vers ${destinationRemote} refusé (non-fast-forward probable, ` +
          `sha destination actuel ${destinationSha ?? 'inconnu'}) : ` +
          (pushResult.stderr || pushResult.stdout || 'sortie vide'),
      };
    }

    return { ok: true, kind: 'pushed', branch, sha: sourceSha };
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

