    // to the exact same forbidden path git will actually write to — a
    // case-sensitive Set/prefix check here would let those bypass the guard.
    const offending = changedPaths.filter((p) => {
      const normalized = path.posix.normalize(p).toLowerCase();
      return (
        META_GOVERN_FORBIDDEN_EXACT.has(normalized) ||
        META_GOVERN_FORBIDDEN_PREFIXES.some((prefix) => normalized.startsWith(prefix))
      );
    });
    return offending.length > 0
      ? `chemins interdits pour meta-govern (hooks/, .claude/settings.json) : ${offending.join(', ')}`
      : undefined;
  }
  const prefix = `${skill}/`;
  const offending = changedPaths.filter((p) => !path.posix.normalize(p).startsWith(prefix));
  return offending.length > 0 ? `chemins hors ${prefix} : ${offending.join(', ')}` : undefined;
}

