/**
 * Forme LIBRE qu'une routine cloud a réellement produite le 2026-07-27 faute
 * de contrat écrit : un fichier PAR job sous `results/reviews/<jobId>.review.json`,
 * note sur 100, dimensions en objet libre. L'import lisait (et lit toujours)
 * `results.json` À LA RACINE — la nuit entière avait donc été perdue en
 * `IMPORT_GAP` alors que le jugement était valide et payé.
 *
 * Cet adaptateur RÉCUPÈRE cette forme ; il ne la légitime pas. Trois
 * garde-fous pour qu'il ne devienne jamais un second contrat toléré :
 *   1. il n'est tenté QUE si `results.json` est absent ou invalide ;
 *   2. il lève TOUJOURS un écart (`gaps`) — donc une conversation du hub —
 *      même quand la conversion réussit parfaitement ;
 *   3. il n'INVENTE aucun jugement : tout champ non dérivable est omis
 *      (il est optionnel côté schéma) ou dégradé vers une valeur qui se
 *      déclare comme telle (`verdict: 'unmeasured'`, exclu du DoG par
 *      conception — voir `ReviewVerdictSchema` dans `src/types/review.ts`).
 * La source de vérité du format reste `docs/evals/results-contract.md`,
 * désormais embarquée dans CHAQUE cargo.
 */
const LegacyDimensionSchema = z
  .object({
    verdict: z.string().optional(),
    score: z.number().optional(),
    summary: z.string().optional(),
    evidence: z.array(z.string()).optional(),
  })
  .passthrough();

const LegacyReviewFileSchema = z
  .object({
    jobId: z.string().min(1).optional(),
    sessionId: z.string().min(1).optional(),
    skill: z.string().min(1).optional(),
    finalScore: z.number().optional(),
    finalScoreScale: z.string().optional(),
    grade: z.number().optional(),
    verdict: z.string().optional(),
    dimensions: z.record(z.string(), LegacyDimensionSchema).optional(),
    rubricVersion: z.string().min(1).optional(),
    graderSessionId: z.string().min(1).optional(),
  })
  .passthrough();
type LegacyReviewFile = z.infer<typeof LegacyReviewFileSchema>;

/**
 * Normalise une note héritée vers l'échelle 0-10 du schéma.
 *
 * `finalScoreScale` fait foi quand il est présent ET reconnu. Absent, l'échelle
 * est DÉDUITE — et c'est la seule déduction que fait cet adaptateur, assumée
 * comme telle : une valeur > 10 ne peut pas être une note sur 10 (le schéma la
 * borne à 10), donc elle est centésimale ; une valeur ≤ 10 est prise sur 10,
 * la seule échelle que le schéma connaisse. Une échelle DÉCLARÉE mais inconnue
 * n'est jamais devinée — on renvoie `undefined`, et l'appelant refuse la
 * conversion plutôt que de publier une note fausse.
 */
function normalizeLegacyGrade(legacy: LegacyReviewFile): number | undefined {
  const raw = legacy.grade ?? legacy.finalScore;
  if (raw === undefined || !Number.isFinite(raw) || raw < 0) return undefined;
  const scale = legacy.finalScoreScale;
  let normalized: number;
  if (scale === '0-100') normalized = raw / 10;
  else if (scale === '0-10') normalized = raw;
  else if (scale !== undefined) return undefined; // échelle déclarée mais inconnue — jamais devinée
  else normalized = raw > 10 ? raw / 10 : raw;
  return normalized >= 0 && normalized <= 10 ? normalized : undefined;
}

/**
 * Une dimension héritée devient UN finding, sévérité `P3` : la sévérité n'est
 * PAS exprimable depuis une note dimensionnelle, et la sur-déclarer
 * (`P1`/`P2`) fabriquerait une alarme que le juge n'a jamais émise. Le
 * libellé porte la note et le verdict d'origine, donc rien du jugement payé
 * n'est perdu — seule la sévérité est délibérément plancher.
 */
function legacyDimensionsToFindings(legacy: LegacyReviewFile): SkillJobFinding[] {
  const findings: SkillJobFinding[] = [];
  for (const [name, dim] of Object.entries(legacy.dimensions ?? {})) {
    // Note dimensionnelle recopiée BRUTE, sans dénominateur : le format
    // hérité n'ayant pas de contrat, l'échelle d'une dimension est inconnue
    // (`/10` fabriquerait une précision que la source ne porte pas).
    const head = [dim.verdict, dim.score !== undefined ? `score ${dim.score}` : undefined]
      .filter(Boolean)
      .join(' · ');
    const evidence = [head, dim.summary, ...(dim.evidence ?? [])].filter(Boolean).join(' — ');
    if (!evidence) continue;
    findings.push({ category: name, evidence, severity: 'P3' });
  }
  return findings;
}

function legacyReviewToImportItem(legacy: LegacyReviewFile): ImportResultItem | undefined {
  if (!legacy.jobId && !legacy.sessionId) return undefined;
  const parsedVerdict = ReviewVerdictSchema.safeParse(legacy.verdict);
  const item: ImportResultItem = {
    kind: legacy.jobId ? 'skillJobGrade' : 'sessionReview',
    ...(legacy.jobId ? { jobId: legacy.jobId } : {}),
    ...(legacy.sessionId && !legacy.jobId ? { sessionId: legacy.sessionId } : {}),
    ...(legacy.skill ? { skill: legacy.skill } : {}),
    // Un verdict hors énumération devient `unmeasured` — la valeur PRÉVUE
    // pour « noté mais non comparable », exclue de la médiane DoG. Jamais un
    // `ok`/`improvement_candidate` déduit d'un seuil inventé ici.
    verdict: parsedVerdict.success ? parsedVerdict.data : 'unmeasured',
    ...(legacy.graderSessionId ? { graderSessionId: legacy.graderSessionId } : {}),
    ...(legacy.rubricVersion ? { rubricVersion: legacy.rubricVersion } : {}),
  };
  // Pas de note exploitable ⇒ on REFUSE de convertir, au lieu de laisser
  // `applyResultSideEffects` retomber sur son défaut `grade: r.grade ?? 0` —
  // qui persisterait « 0/10 », c'est-à-dire un travail jugé catastrophique,
  // là où la vérité est « note illisible ». Le fichier part alors dans les
  // `rejected` et devient visible dans l'écart.
