  const findings = legacyDimensionsToFindings(legacy);
  if (findings.length > 0) item.findings = findings;
  if (!legacy.jobId && legacy.sessionId) item.sessionState = 'reviewed';
  return ImportResultItemSchema.safeParse(item).success ? item : undefined;
}

