 * caller-SUPPLIED sha, never one it resolves itself — stays unchanged for its
 * other legitimate caller, a one-off Claude/CLI session passing an
 * independently-verified sha).
 *
 * Runs under the same dedicated `evals-apply.lock` as every other mutator of
 * `target.integrationClone` in this file — the clone/fetch this performs is
 * itself a mutation of that shared directory, so it must not race a
 * concurrent `applyProposal`/`revertProposal` touching the same clone.
 */
export async function resolveCurrentMainSha(proposalId: string, ctx: ApplyContext): Promise<string> {
  return withApplyLock('resolveCurrentMainSha', async () => {
    const proposal = await getImprovementProposal(proposalId);
    if (!proposal) throw new Error(`ImprovementProposal introuvable : ${proposalId}`);
    const target = resolveTarget(proposal, ctx);
    ensureIntegrationClone(target);
    const sha = gitRevParseOrUndefined('origin/main', target.integrationClone);
    if (sha === undefined) {
      throw new Error(`main introuvable sur ${target.remote} (proposal ${proposalId})`);
    }
    return sha;
  });
}

