/** `AAAA-MM-JJ` strict — un `--date` libre deviendrait un nom de ref git. */
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

export async function cmdImport(opts: { dryRun: boolean; from?: string; date?: string }): Promise<void> {
  // Validé AVANT le verrou : `fail()` termine le process, un `fail` posé
  // après `acquireLock` laisserait un verrou orphelin derrière lui (le
  // `finally` qui le relâche ne s'exécuterait jamais).
  if (opts.date !== undefined && !ISO_DATE_RE.test(opts.date)) {
    fail(`--date invalide : "${opts.date}" — attendu AAAA-MM-JJ`);
  }
  const lock = await acquireLock('import');
  if (!lock.acquired) {
    printNoop(lock.reason ?? 'verrou indisponible', lock.held);
    return;
  }

  const scratch = await mkdtemp(path.join(os.tmpdir(), 'evals-import-'));
  try {
    execFileSync('git', ['init', '-q', scratch]);
    const target = opts.from ?? cargoRemoteUrl();
    // `--date` : rattrapage d'une nuit PASSÉE. Sans lui, une nuit manquée
    // (Mac éteint, réseau coupé, ou — vécu le 2026-07-27 — un résultat cloud
    // déposé au mauvais chemin) est DÉFINITIVEMENT irrécupérable : le jour
    // suivant, `todayUtcDate()` a changé et plus aucune commande ne regarde
    // l'ancienne branche. Validé strictement : cette valeur devient un nom de
    // ref git (`results/<date>`), elle ne peut pas être du texte libre.
    const date = opts.date ?? todayUtcDate();
    const resultsRef = `results/${date}`;
    const cargoRef = `cargo/${date}`;

    const resultsBranch = await fetchBranchContent(target, resultsRef, scratch);
    if (!resultsBranch) {
      // Nuit no-op légitime : si le manifeste cargo du jour existe et ne
      // contient AUCUN item `export` (que du local_only/deferred), le contrat
      // de la routine cloud est de ne rien pousser — l'absence de results/
      // est alors ATTENDUE, pas un écart. Ouvrir une conversation d'approbation

