    // (voir `evalsConfig.ts`) — sans cette clé, `EvalsConfigSchema.parse`
    // lève dès que `loadEvalsConfig()` charge ce fichier.
    localJudge: { provider: 'anthropic', model: 'claude-opus-5', effort: 'high' },
  },
  reviewSince: '2020-01-01',
  minTier: 'medium',
  quiescenceHours: 3,
  caps: { sessionsPerNight: 8, maxTranscriptBytes: 6_000_000, maxCargoBytes: 50_000_000 },
  schedulingPolicy: { freshRatio: 0.8, staleRatio: 0.2, maxAgeDays: 30 },
  projectPolicy: { mode: 'allowlist', projects: ['demo-project'] },
  cargoSkills: ['adversarial-pr-review'],
  // Bloc opérationnel top-level `localJudge` — REQUIS depuis le retrait de
  // son propre `.default(...)` sur `EvalsConfigSchema` (revue adversariale
  // round 2, "le garde anti-dépense-silencieuse reste TROUÉ (jumeau
  // manqué)" — voir `evalsConfig.ts`) : sans cette clé, `EvalsConfigSchema.parse`
