  // l'ancien `EVALS_LOCAL_JUDGE_DEFAULT` du schéma (désormais supprimé) pour
  // ne rien changer au comportement des tests de ce fichier qui ne
  // surchargent pas `localJudge` via `seedConfig(dir, { localJudge: {...} })`.
  localJudge: { enabled: true, maxPerNight: 2, timeoutMinutes: 15, maxBudgetUsd: 2.5, maxAttempts: 3 },
};

async function seedConfig(rootDir: string, overrides: Record<string, unknown> = {}): Promise<void> {
  const cfg = { ...FIXTURE_CONFIG, ...overrides };
  await mkdir(path.join(rootDir, 'config'), { recursive: true });
  await writeFile(path.join(rootDir, 'config', 'evals.json'), JSON.stringify(cfg, null, 2), 'utf8');
}

/**
 * Also sets `process.env.WORKSTATION_ROOT = dir` — required for any DIRECT
 * (in-process) call into `store`/`chipStore`/`conversationStore` right after
 * this returns: those resolve `dataRoot()`/`root()` from the CURRENT
 * process's env at CALL TIME (see `server/config.ts`), which is a SEPARATE
 * concern from `run()`'s subprocess `env` override — a subprocess never
 * reads the outer test process's env. Every test in this file uses its own
 * fresh root (never a single shared one), so this must be set per test,
 * immediately before any fixture is created.
 */
async function freshRoot(configOverrides: Record<string, unknown> = {}): Promise<string> {
  const dir = await realpath(await mkdtemp(path.join(os.tmpdir(), 'wsevalsrec-')));
  tmpRoots.push(dir);
  await seedConfig(dir, configOverrides);
  process.env.WORKSTATION_ROOT = dir;
  return dir;
}

afterAll(async () => {
  await Promise.all(tmpRoots.map((d) => rm(d, { recursive: true, force: true })));
});

