function mergeApprovedBranchIntoMain(
  proposal: ImprovementProposal,
  target: RepoIntegrationTarget,
  branch: string,
): { ok: true; mergeSha: string } | { ok: false; reason: string; cause: MergeFailureCause } {
  ensureIntegrationClone(target);
  // finding #5, round 3 (P2) — `git checkout -B` below refuses to switch
  // branches while the index carries unresolved conflicts left by a PREVIOUS
  // merge/revert on this same shared clone that was interrupted (crash, this
  // module's own `SIGKILL` timeout, …) before reaching its own best-effort
  // `--abort`. `checkout -B` itself is a raw `git()` call, not `gitTry`, so
  // that failure would crash uncaught. Best-effort abort of BOTH kinds of
  // in-progress operation this file ever leaves mid-flight (merge here,
  // revert in `revertMergeCommitOnMain`) guarantees a clean tree before the
  // checkout, regardless of which of the two half-finished a prior run.
  abortMergeBestEffort(target.integrationClone);
  abortRevertBestEffort(target.integrationClone);

  const remoteMainSha = gitRevParseOrUndefined('origin/main', target.integrationClone);
  if (remoteMainSha === undefined) {
    return {
      ok: false,
      reason: `main introuvable sur ${target.remote}`,
      cause: 'target-main-missing',
    };
  }
  if (remoteMainSha !== proposal.beforeSha) {
    return {
      ok: false,
      reason:
        `HEAD réel de main (${remoteMainSha}) diverge du beforeSha de la proposal ` +
        `(${proposal.beforeSha}) — §11 #17, merge refusé`,
      cause: 'before-sha-mismatch',
    };
  }

  const branchSha = gitRevParseOrUndefined(`origin/${branch}`, target.integrationClone);
  if (branchSha === undefined) {
    return {
      ok: false,
      reason: `branche ${branch} introuvable sur ${target.remote}`,
      cause: 'branch-missing',
    };
  }

  git(['checkout', '-B', 'main', 'origin/main'], target.integrationClone);
  // finding #5, round 2 — a real content conflict makes `git merge` exit
  // non-zero; previously nothing caught that, so `execFileSync` threw
  // straight through this function's declared ok/false return type,
  // leaving `MERGE_HEAD` and unresolved index entries in the shared
  // integration clone for the next retry to inherit. `gitTry` + best-effort
  // `--abort` restores a clean tree before reporting the failure normally.
  const mergeResult = gitTry(
    ['merge', '--no-ff', `origin/${branch}`, '-m', `merge: ${branch} (proposal ${proposal.id})`],
    target.integrationClone,
  );
  if (!mergeResult.ok) {
