// Lot 6 — rejeu de bout en bout de la nuit du 2026-07-29, ENTIÈREMENT local.
// Aucune variable ne pointe vers ~/.claude/skills ; WORKSTATION_ROOT isole
// data/ dans un dossier temporaire pour toute la durée du script.
import path from 'node:path';
import { promises as fs } from 'node:fs';

process.env.WORKSTATION_ROOT = process.argv[2];
const BASE = process.argv[3];

const { transportImproveBranch } = await import(
  '/Users/elmabi/Desktop/my-projets/workstation/server/services/reviews/improveBranchTransport.ts'
);
const { createGatedProposal, applyProposal, proposalBranchName } = await import(
  '/Users/elmabi/Desktop/my-projets/workstation/server/services/reviews/apply.ts'
);
const { getConversation, saveConversation } = await import(
  '/Users/elmabi/Desktop/my-projets/workstation/server/services/conversationStore.ts'
);

const NIGHT_DATE = '2026-07-29';
const SKILLS = ['session-review', 'adversarial-pr-review'];

const cargoRemote = path.join(BASE, 'cargo-fixture.git');
const destinationRemote = path.join(BASE, 'skills-fixture.git');
const installRoot = path.join(BASE, 'install-root');
const integrationClone = path.join(BASE, 'integration-clone');
await fs.mkdir(installRoot, { recursive: true });

const ctx = {
  skillRepo: { remote: destinationRemote, integrationClone, installRoot },
};

const results: Record<string, unknown> = {};

for (const skill of SKILLS) {
  const branch = proposalBranchName(
    { skill, id: 'n/a', version: 1, updatedAt: new Date().toISOString() },
    NIGHT_DATE,
  );
  console.log(`\n=== ${skill} — branche attendue ${branch} ===`);

  const transportResult = await transportImproveBranch({ cargoRemote, destinationRemote, branch });
  console.log('transport:', JSON.stringify(transportResult));
  if (!transportResult.ok) {
    results[skill] = { stage: 'transport', ...transportResult };
    continue;
  }

  const diffPath = path.join(BASE, `${skill}.diff`);
  const backupPath = path.join(BASE, `${skill}.backup-placeholder`);
  await fs.writeFile(diffPath, `dry-run — voir ${branch}\n`);
  await fs.writeFile(backupPath, 'placeholder\n');

  let proposal;
  try {
    const { proposal: p } = await createGatedProposal({
      skill,
      fromJobs: ['dry-run-lot6'],
      beforeSha: 'f9f47cc6d60d22cb180a486f58fc67519870d7b4',
      diffPath,
      backupPath,
      jobsSummary: 'Rejeu dry-run lot 6',
      diffText: `Rejeu dry-run de ${branch}`,
      expectedEffect: 'N/A — rejeu de vérification',
