import path from 'node:path';

import { dataRoot } from '../../config';
import { isSafeSegment } from '../slug';

/**
 * Path resolution for the Banc d'essai (skill continuous-evaluation) stores.
 * Every path is derived from `dataRoot()` at CALL TIME — never a hardcoded
 * `data/` segment — so a dev instance (`WORKSTATION_DATA_ROOT`) and tests
 * (`WORKSTATION_ROOT`/`WORKSTATION_DATA_ROOT`) stay isolated from prod, exactly
 * like every other subsystem in `server/config.ts`.
 */

export function reviewsDir(): string {
  return path.join(dataRoot(), 'reviews');
}

export function skillJobsDir(): string {
  return path.join(reviewsDir(), 'skill-jobs');
}

export function sessionsDir(): string {
  return path.join(reviewsDir(), 'sessions');
}

export function improvementsDir(): string {
  return path.join(reviewsDir(), 'improvements');
}

/** `dataRoot()/reviews/skill-jobs/<id>.json`. Throws on an unsafe id. */
export function skillJobPath(id: string): string {
  if (!isSafeSegment(id)) {
    throw new Error(`Invalid skill job id: ${id}`);
  }
  return path.join(skillJobsDir(), `${id}.json`);
}

/** `dataRoot()/reviews/sessions/<sessionId>.json`. Throws on an unsafe id. */
export function sessionStampPath(sessionId: string): string {
  if (!isSafeSegment(sessionId)) {
    throw new Error(`Invalid session id: ${sessionId}`);
  }
  return path.join(sessionsDir(), `${sessionId}.json`);
}

/** `dataRoot()/reviews/improvements/<id>.json`. Throws on an unsafe id. */
export function improvementProposalPath(id: string): string {
  if (!isSafeSegment(id)) {
    throw new Error(`Invalid improvement proposal id: ${id}`);
  }
  return path.join(improvementsDir(), `${id}.json`);
}

