export async function getSessionStamp(sessionId: string): Promise<SessionReviewStamp | null> {
  return readSessionStampFile(sessionStampPath(sessionId));
}

export async function listSessionStamps(filter?: {
  projectSlug?: string;
  state?: SessionReviewState[];
}): Promise<SessionReviewStamp[]> {
  let stamps = await listDirEntities(sessionsDir(), SessionReviewStampSchema);
  if (filter?.projectSlug) stamps = stamps.filter((s) => s.projectSlug === filter.projectSlug);
  if (filter?.state) {
    const states = new Set(filter.state);
    stamps = stamps.filter((s) => states.has(s.state));
  }
  return stamps;
}

export async function updateSessionStamp(
  sessionId: string,
  patch: Partial<Omit<SessionReviewStamp, 'schemaVersion' | 'sessionId'>>,
  expectedUpdatedAt: string,
): Promise<SessionReviewStamp> {
  const filePath = sessionStampPath(sessionId);
  const current = await readSessionStampFile(filePath);
  if (!current) throw new ReviewNotFoundError('sessionStamp', sessionId);
  if (current.updatedAt !== expectedUpdatedAt) {
    throw new ReviewConflictError('sessionStamp', sessionId, current);
  }

  const nextState = patch.state ?? current.state;
  if (nextState !== current.state) {
    const allowed = SESSION_STAMP_TRANSITIONS[current.state] ?? [];
    if (!allowed.includes(nextState)) {
      throw new ReviewStateTransitionError('sessionStamp', sessionId, current.state, nextState);
    }
  }

  const now = new Date().toISOString();
  const next = SessionReviewStampSchema.parse({
    ...current,
    ...patch,
    schemaVersion: 1,
    sessionId,
    updatedAt: now,
  });
  await atomicWrite(filePath, JSON.stringify(next, null, 2));
  const persisted = await readSessionStampFile(filePath);
  if (!persisted) throw new Error('Failed to re-read persisted session stamp');
  return persisted;
}

