export async function listSkillJobs(filter?: {
  skill?: string;
  state?: SkillJobState[];
}): Promise<SkillJob[]> {
  let jobs = await listDirEntities(skillJobsDir(), SkillJobSchema);
  if (filter?.skill) jobs = jobs.filter((j) => j.skill === filter.skill);
  if (filter?.state) {
    const states = new Set(filter.state);
    jobs = jobs.filter((j) => states.has(j.state));
  }
  return jobs;
}

/**
 * Update a SkillJob. `expectedUpdatedAt` must equal the on-disk `updatedAt`
 * (optimistic lock, throws `ReviewConflictError` on mismatch). A `state` in
 * `patch` that differs from the current state must be a legal edge in
 * `SKILL_JOB_TRANSITIONS` (throws `ReviewStateTransitionError` otherwise).
 */
export async function updateSkillJob(
  id: string,
  patch: Partial<Omit<SkillJob, 'schemaVersion' | 'id'>>,
  expectedUpdatedAt: string,
): Promise<SkillJob> {
  const filePath = skillJobPath(id);
  const current = await readSkillJobFile(filePath);
  if (!current) throw new ReviewNotFoundError('skillJob', id);
  if (current.updatedAt !== expectedUpdatedAt) {
    throw new ReviewConflictError('skillJob', id, current);
  }

  const nextState = patch.state ?? current.state;
  if (nextState !== current.state) {
    const allowed = SKILL_JOB_TRANSITIONS[current.state] ?? [];
    if (!allowed.includes(nextState)) {
      throw new ReviewStateTransitionError('skillJob', id, current.state, nextState);
    }
  }

  const now = new Date().toISOString();
  const next = SkillJobSchema.parse({ ...current, ...patch, schemaVersion: 1, id, updatedAt: now });
  await atomicWrite(filePath, JSON.stringify(next, null, 2));

