1	/**
2	 * lessonsAggregate — read-only aggregation of `SkillJobReview.findings`
3	 * (Lot 7, chantier `rail-application-et-boucle-lecons`) across reviewed
4	 * `SessionReviewStamp`s and, optionally, graded `SkillJob`s, grouped by
5	 * `category`, over a time window.
6	 *
7	 * Purpose: today a finding produced by a session-review or a skill-job grade
8	 * (`SkillJobFinding`, `src/types/review.ts` ~L126) sits alone in its own
9	 * stamp/job file — nothing reads them SIDE BY SIDE to answer "does this keep
10	 * happening?". This module is that read: it groups every finding it can see
11	 * by `category` and flags the categories that meet the SAME recurrence rule
12	 * the cloud judge already applies when deciding whether a failure is worth
13	 * turning into an improvement proposal (`docs/evals/routine-cloud-prompt.md`,
14	 * step 4 — quoted verbatim, never re-derived): "même catégorie d'échec sur
15	 * ≥ 2 jobs, ou un P1 flagrant". Applied here across BOTH sessions and skill
16	 * jobs (not jobs alone): a category is `recurring` once it has struck ≥ 2
17	 * DISTINCT sources (session or job, counted together) or at least one `P1`
18	 * finding, whichever comes first.
19	 *
20	 * STRICTLY READ-ONLY — exigence explicite du Lot 7. This module calls only
21	 * `listSessionStamps`/`listSkillJobs` (both pure reads over `data/reviews/**`)
22	 * and `loadEvalsConfig` (pure read over `config/evals.json`). It never calls
23	 * `updateSessionStamp`/`updateSkillJob`/`createChipFromInput`/`saveConversation`
24	 * or any other mutating function, never touches a transcript (`transcriptPath`
25	 * is not read here — only the already-computed `review` block), and makes no
26	 * network/Convex call. A dedicated test (`lessonsAggregate.test.ts`, "aucun
27	 * effet de bord") snapshots the fixture root's file listing + contents before
28	 * and after a call and asserts byte-for-byte equality.
29	 *
30	 * SkillJobs are included by default (`includeSkillJobs: true`) — the Lot 7
31	 * brief explicitly allows it ("et des SkillJobs notés, si l'agrégat reste
32	 * lisible") and a category that only ever shows up in skill-job grades (never
33	 * in a session-review) would otherwise never surface as recurring even after
34	 * striking twice. A job counts as "noted" when it carries a `review` block at
35	 * all (`job.review !== undefined`), regardless of its current `state`
36	 * (`graded`/`improvement_proposed`/`closed` all keep the review — see
37	 * `SKILL_JOB_TRANSITIONS` in `store.ts`, none of those edges clear `review`).
38	 *
39	 * Window: `since` (`AAAA-MM-JJ`) defaults to `config/evals.json`'s
40	 * `reviewSince` — the SAME default the rest of this CLI already uses to scope
41	 * "what's worth reading" (`cmdPending` in `server/cli/evals.ts` filters
42	 * `capturedAt >= cfg.reviewSince` the identical way). Comparison is a plain
43	 * string `>=` against each source's own occurrence timestamp (`reviewedAt`
44	 * for a session, `review.gradedAt` for a job) — both are ISO datetimes, and a
45	 * date-only `since` sorts correctly before same-day timestamps because it is
46	 * a strict prefix, exactly like the existing `cmdPending` comparison.
47	 */
48	import {
49	  type FindingSeverity,
50	  type SessionReviewStamp,
51	  type SkillJob,
52	} from '../../../src/types/review';
53	import { listSessionStamps, listSkillJobs } from './store';
54	import { loadEvalsConfig } from './evalsConfig';
55	import { projectSlugFromRepoRoot } from '../slug';
56	
57	/** Quoted verbatim from `docs/evals/routine-cloud-prompt.md` (step 4) — the
58	 *  recurrence rule this module applies, never re-derived or re-tuned here. */
59	export const RECURRENCE_RULE_LABEL =
60	  "même catégorie d'échec sur ≥ 2 jobs, ou un P1 flagrant";
61	
62	/** One finding occurrence, traced back to its source (session or skill job)
63	 *  so a reader can jump straight to the record that produced it. */
64	export interface LessonOccurrence {
65	  sourceKind: 'session' | 'skillJob';
66	  /** `sessionId` for a session source, `SkillJob.id` for a skill-job source. */
67	  sourceId: string;
68	  projectSlug?: string;
69	  severity: FindingSeverity;
70	  evidence: string;
71	  /** ISO datetime the finding was produced (`reviewedAt`/`review.gradedAt`). */
72	  occurredAt: string;
73	}
74	
75	/** One category's aggregate across every occurrence found in the window. */
76	export interface LessonCategorySummary {
77	  category: string;
78	  occurrences: LessonOccurrence[];
79	  count: number;
80	  severities: FindingSeverity[];
81	  /** Distinct `projectSlug`s among this category's occurrences (sessions
82	   *  carry it directly; skill jobs derive it from `repoRoot`). */
83	  projects: string[];
84	  /** Distinct source ids (session or job) — the basis for the ≥2 count of
85	   *  the recurrence rule, NOT a raw finding count (one source can log the
86	   *  same category twice and that must not fake a second distinct source). */
87	  distinctSources: string[];
88	  firstSeenAt: string;
89	  lastSeenAt: string;
90	  /** True once `RECURRENCE_RULE_LABEL` is satisfied for this category. */
91	  recurring: boolean;
92	  recurringReason: 'distinct_sources' | 'p1_finding' | null;
93	}
94	
95	export interface LessonsAggregate {
96	  since: string;
97	  generatedAt: string;
98	  includeSkillJobs: boolean;
99	  /** How many reviewed sessions / graded skill jobs were inspected in the
100	   *  window, BEFORE filtering out the ones with no findings — lets a reader
101	   *  tell "no findings on this window" apart from "no reviewed sessions at
102	   *  all in this window". */
103	  sourcesConsidered: { sessions: number; skillJobs: number };
104	  totalFindings: number;
105	  categories: LessonCategorySummary[];
106	}
107	
108	export interface AggregateLessonsOptions {
109	  /** `AAAA-MM-JJ`; defaults to `config/evals.json`'s `reviewSince`. */
110	  since?: string;
111	  /** Defaults to `true` — see module docstring for why. */
112	  includeSkillJobs?: boolean;
113	}
114	
115	function projectSlugForJob(job: SkillJob): string {
116	  return projectSlugFromRepoRoot(job.repoRoot);
117	}
118	
119	/** Group every finding from the given reviewed sessions / graded skill jobs
120	 *  by `category`. Each finding becomes one `LessonOccurrence` traced back to
121	 *  its source (`session:<sessionId>` or `skillJob:<jobId>` isn't stored as a
122	 *  single string — `sourceKind`+`sourceId` stay separate fields so a session
123	 *  and a job that happen to share an id text can never collide). */
124	function groupOccurrencesByCategory(
125	  sessionsInWindow: SessionReviewStamp[],
126	  skillJobsInWindow: SkillJob[],
127	): Map<string, LessonOccurrence[]> {
128	  const grouped = new Map<string, LessonOccurrence[]>();
129	  const push = (category: string, occ: LessonOccurrence) => {
130	    const list = grouped.get(category) ?? [];
131	    list.push(occ);
132	    grouped.set(category, list);
133	  };
134	
135	  for (const stamp of sessionsInWindow) {
136	    if (!stamp.review) continue;
137	    const occurredAt = stamp.reviewedAt ?? stamp.updatedAt;
138	    for (const f of stamp.review.findings) {
139	      push(f.category, {
140	        sourceKind: 'session',
141	        sourceId: stamp.sessionId,
142	        projectSlug: stamp.projectSlug,
143	        severity: f.severity,
144	        evidence: f.evidence,
145	        occurredAt,
146	      });
147	    }
148	  }
149	
150	  for (const job of skillJobsInWindow) {
151	    if (!job.review) continue;
152	    const occurredAt = job.review.gradedAt;
153	    for (const f of job.review.findings) {
154	      push(f.category, {
155	        sourceKind: 'skillJob',
156	        sourceId: job.id,
157	        projectSlug: projectSlugForJob(job),
158	        severity: f.severity,
