/**
 * lessonsAggregate — read-only aggregation of `SkillJobReview.findings`
 * (Lot 7, chantier `rail-application-et-boucle-lecons`) across reviewed
 * `SessionReviewStamp`s and, optionally, graded `SkillJob`s, grouped by
 * `category`, over a time window.
 *
 * Purpose: today a finding produced by a session-review or a skill-job grade
 * (`SkillJobFinding`, `src/types/review.ts` ~L126) sits alone in its own
 * stamp/job file — nothing reads them SIDE BY SIDE to answer "does this keep
 * happening?". This module is that read: it groups every finding it can see
 * by `category` and flags the categories that meet the SAME recurrence rule
 * the cloud judge already applies when deciding whether a failure is worth
 * turning into an improvement proposal (`docs/evals/routine-cloud-prompt.md`,
 * step 4 — quoted verbatim, never re-derived): "même catégorie d'échec sur
 * ≥ 2 jobs, ou un P1 flagrant". Applied here across BOTH sessions and skill
 * jobs (not jobs alone): a category is `recurring` once it has struck ≥ 2
 * DISTINCT sources (session or job, counted together) or at least one `P1`
 * finding, whichever comes first.
 *
 * STRICTLY READ-ONLY — exigence explicite du Lot 7. This module calls only
 * `listSessionStamps`/`listSkillJobs` (both pure reads over `data/reviews/**`)
 * and `loadEvalsConfig` (pure read over `config/evals.json`). It never calls
 * `updateSessionStamp`/`updateSkillJob`/`createChipFromInput`/`saveConversation`
 * or any other mutating function, never touches a transcript (`transcriptPath`
 * is not read here — only the already-computed `review` block), and makes no
 * network/Convex call. A dedicated test (`lessonsAggregate.test.ts`, "aucun
 * effet de bord") snapshots the fixture root's file listing + contents before
 * and after a call and asserts byte-for-byte equality.
 *
 * SkillJobs are included by default (`includeSkillJobs: true`) — the Lot 7
 * brief explicitly allows it ("et des SkillJobs notés, si l'agrégat reste
 * lisible") and a category that only ever shows up in skill-job grades (never
 * in a session-review) would otherwise never surface as recurring even after
 * striking twice. A job counts as "noted" when it carries a `review` block at
 * all (`job.review !== undefined`), regardless of its current `state`
 * (`graded`/`improvement_proposed`/`closed` all keep the review — see
 * `SKILL_JOB_TRANSITIONS` in `store.ts`, none of those edges clear `review`).
 *
 * Window: `since` (`AAAA-MM-JJ`) defaults to `config/evals.json`'s
 * `reviewSince` — the SAME default the rest of this CLI already uses to scope
 * "what's worth reading" (`cmdPending` in `server/cli/evals.ts` filters
 * `capturedAt >= cfg.reviewSince` the identical way). Comparison is a plain
 * string `>=` against each source's own occurrence timestamp (`reviewedAt`
 * for a session, `review.gradedAt` for a job) — both are ISO datetimes, and a
 * date-only `since` sorts correctly before same-day timestamps because it is
 * a strict prefix, exactly like the existing `cmdPending` comparison.
 */
import {
  type FindingSeverity,
  type SessionReviewStamp,
  type SkillJob,
} from '../../../src/types/review';
import { listSessionStamps, listSkillJobs } from './store';
import { loadEvalsConfig } from './evalsConfig';
import { projectSlugFromRepoRoot } from '../slug';

/** Quoted verbatim from `docs/evals/routine-cloud-prompt.md` (step 4) — the
 *  recurrence rule this module applies, never re-derived or re-tuned here. */
export const RECURRENCE_RULE_LABEL =
  "même catégorie d'échec sur ≥ 2 jobs, ou un P1 flagrant";

/** One finding occurrence, traced back to its source (session or skill job)
 *  so a reader can jump straight to the record that produced it. */
export interface LessonOccurrence {
  sourceKind: 'session' | 'skillJob';
  /** `sessionId` for a session source, `SkillJob.id` for a skill-job source. */
  sourceId: string;
  projectSlug?: string;
  severity: FindingSeverity;
  evidence: string;
  /** ISO datetime the finding was produced (`reviewedAt`/`review.gradedAt`). */
  occurredAt: string;
}

/** One category's aggregate across every occurrence found in the window. */
export interface LessonCategorySummary {
  category: string;
  occurrences: LessonOccurrence[];
  count: number;
  severities: FindingSeverity[];
  /** Distinct `projectSlug`s among this category's occurrences (sessions
   *  carry it directly; skill jobs derive it from `repoRoot`). */
  projects: string[];
  /** Distinct source ids (session or job) — the basis for the ≥2 count of
   *  the recurrence rule, NOT a raw finding count (one source can log the
   *  same category twice and that must not fake a second distinct source). */
  distinctSources: string[];
  firstSeenAt: string;
  lastSeenAt: string;
  /** True once `RECURRENCE_RULE_LABEL` is satisfied for this category. */
  recurring: boolean;
  recurringReason: 'distinct_sources' | 'p1_finding' | null;
}

export interface LessonsAggregate {
  since: string;
  generatedAt: string;
  includeSkillJobs: boolean;
  /** How many reviewed sessions / graded skill jobs were inspected in the
   *  window, BEFORE filtering out the ones with no findings — lets a reader
   *  tell "no findings on this window" apart from "no reviewed sessions at
   *  all in this window". */
  sourcesConsidered: { sessions: number; skillJobs: number };
  totalFindings: number;
  categories: LessonCategorySummary[];
}

export interface AggregateLessonsOptions {
  /** `AAAA-MM-JJ`; defaults to `config/evals.json`'s `reviewSince`. */
  since?: string;
  /** Defaults to `true` — see module docstring for why. */
  includeSkillJobs?: boolean;
}

function projectSlugForJob(job: SkillJob): string {
  return projectSlugFromRepoRoot(job.repoRoot);
}

/** Group every finding from the given reviewed sessions / graded skill jobs
 *  by `category`. Each finding becomes one `LessonOccurrence` traced back to
 *  its source (`session:<sessionId>` or `skillJob:<jobId>` isn't stored as a
 *  single string — `sourceKind`+`sourceId` stay separate fields so a session
 *  and a job that happen to share an id text can never collide). */
function groupOccurrencesByCategory(
  sessionsInWindow: SessionReviewStamp[],
  skillJobsInWindow: SkillJob[],
): Map<string, LessonOccurrence[]> {
  const grouped = new Map<string, LessonOccurrence[]>();
  const push = (category: string, occ: LessonOccurrence) => {
    const list = grouped.get(category) ?? [];
    list.push(occ);
    grouped.set(category, list);
  };

  for (const stamp of sessionsInWindow) {
    if (!stamp.review) continue;
    const occurredAt = stamp.reviewedAt ?? stamp.updatedAt;
    for (const f of stamp.review.findings) {
      push(f.category, {
        sourceKind: 'session',
        sourceId: stamp.sessionId,
        projectSlug: stamp.projectSlug,
        severity: f.severity,
        evidence: f.evidence,
        occurredAt,
      });
    }
  }

  for (const job of skillJobsInWindow) {
    if (!job.review) continue;
    const occurredAt = job.review.gradedAt;
    for (const f of job.review.findings) {
      push(f.category, {
        sourceKind: 'skillJob',
        sourceId: job.id,
        projectSlug: projectSlugForJob(job),
        severity: f.severity,
        evidence: f.evidence,
        occurredAt,
      });
    }
  }

  return grouped;
}

function summarizeCategory(category: string, occs: LessonOccurrence[]): LessonCategorySummary {
  const distinctSources = Array.from(new Set(occs.map((o) => `${o.sourceKind}:${o.sourceId}`))).sort();
  const severities = (Array.from(new Set(occs.map((o) => o.severity))) as FindingSeverity[]).sort();
  const projects = Array.from(
    new Set(occs.map((o) => o.projectSlug).filter((p): p is string => Boolean(p))),
  ).sort();
  const sortedByDate = [...occs].sort((a, b) => a.occurredAt.localeCompare(b.occurredAt));
  const firstSeenAt = sortedByDate[0]?.occurredAt ?? '';
  const lastSeenAt = sortedByDate[sortedByDate.length - 1]?.occurredAt ?? '';

  const hasP1 = severities.includes('P1');
  const recurring = distinctSources.length >= 2 || hasP1;
  const recurringReason: LessonCategorySummary['recurringReason'] = hasP1
    ? 'p1_finding'
    : distinctSources.length >= 2
      ? 'distinct_sources'
      : null;

  return {
    category,
    occurrences: sortedByDate,
    count: occs.length,
    severities,
    projects,
    distinctSources,
    firstSeenAt,
    lastSeenAt,
    recurring,
    recurringReason,
  };
}

/**
 * Aggregate `review.findings` across reviewed sessions (and, unless disabled,
 * graded skill jobs) by `category`, over `[since, now]`. Pure read — see
 * module docstring for the exact set of calls this makes.
 */
export async function aggregateLessons(
  options: AggregateLessonsOptions = {},
): Promise<LessonsAggregate> {
  const includeSkillJobs = options.includeSkillJobs ?? true;
  const since = options.since ?? (await loadEvalsConfig()).reviewSince;

  const sessionStamps = await listSessionStamps({ state: ['reviewed'] });
  const skillJobs = includeSkillJobs ? await listSkillJobs() : [];

  const sessionsInWindow = sessionStamps.filter((s) => (s.reviewedAt ?? s.updatedAt) >= since);
  const skillJobsInWindow = skillJobs.filter((j) => j.review !== undefined && j.review.gradedAt >= since);

  const grouped = groupOccurrencesByCategory(sessionsInWindow, skillJobsInWindow);

  const categories: LessonCategorySummary[] = Array.from(grouped.entries())
    .map(([category, occs]) => summarizeCategory(category, occs))
    .sort((a, b) => b.count - a.count || a.category.localeCompare(b.category));

  const totalFindings = categories.reduce((sum, c) => sum + c.count, 0);

  return {
    since,
    generatedAt: new Date().toISOString(),
    includeSkillJobs,
    sourcesConsidered: {
      sessions: sessionsInWindow.length,
      skillJobs: skillJobsInWindow.length,
    },
    totalFindings,
    categories,
  };
}

