#!/usr/bin/env node
// Second Brain — digest mémoire au démarrage de session (BRIEF-19).
// Global (~/.claude/settings.json), ajouté au tableau hooks.SessionStart
// existant — jamais un remplacement des autres entrées.
//
// Deux fonctions, décidées au plan 2026-07-11-chantier-hook-sessionstart-memoire :
//  1. POUSSER un digest frugal : 3-5 memories du projet courant, lues dans le
//     miroir JSON nocturne LOCAL du Second Brain (jamais Convex en direct —
//     latence + egress, leçon codifiée), scopes public/professionnel
//     uniquement, ≤ ~500 tokens.
//  2. APPRENDRE à la session qu'elle peut INTERROGER le brain à la demande
//     (pied d'instruction fixe) : un blocage — surtout sur un outil — a
//     peut-être déjà été résolu et payé une fois.
//
// Fiabilité avant richesse : fail-open ABSOLU (toute anomalie → exit 0
// silencieux), lecture seule stricte, aucun réseau, aucun spawn. Un hook
// mémoire qui casse un seul démarrage serait désinstallé dans la semaine.
import { homedir } from 'node:os';
import { readFileSync, statSync } from 'node:fs';
import path from 'node:path';

const SCOPE_ROOT = path.join(homedir(), 'Desktop', 'my-projets');
const MIRROR = path.join(SCOPE_ROOT, 'second-brain', 'data', 'mirror', 'json', 'memories.json');
const MAX_CHARS = 2000; // ~500 tokens — budget TOTAL (digest + pied)
const MAX_MEMORIES = 5;
const TEXT_TRUNC = 280;
const BONUS_KINDS = new Set(['leçon', 'décision', 'convention']);

// Le pied d'instruction (fonction 2) — jamais tronqué : c'est la liste de
// memories qui cède la place, pas lui.
const FOOTER =
  'Le Second Brain contient bien plus que ce digest. En cas de blocage — surtout ' +
  'sur un outil (CLI, MCP, daemon, harnais) — interroge-le AVANT de réessayer à ' +
  "l'aveugle : `bun run --cwd ~/Desktop/my-projets/second-brain cli/index.ts " +
  'search "<ton blocage>"` (ou `memory_search` du MCP workstation-bus) — Franck ' +
  'y a peut-être déjà payé cette erreur.';

async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks).toString('utf8');
}

// Slug projet = kebab-case du premier segment sous ~/Desktop/my-projets —
// même règle déterministe que le skill brain-capture, et la forme que les
// memories du miroir utilisent réellement (workstation, second-brain, …).
function projectSlugFromCwd(resolvedCwd) {
  const rel = path.relative(SCOPE_ROOT, resolvedCwd);
  if (rel.startsWith('..') || rel === '') return null;
  const first = rel.split(path.sep)[0];
  const slug = first
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || null;
}

function main() {
  return readStdin().then((raw) => {
    let event;
    try {
      event = JSON.parse(raw);
    } catch {
      process.exit(0); // stdin malformé — fail-open
    }

    const cwd = typeof event.cwd === 'string' && event.cwd.length > 0 ? event.cwd : process.cwd();
    const resolvedCwd = path.resolve(cwd);
    const inScope = resolvedCwd === SCOPE_ROOT || resolvedCwd.startsWith(SCOPE_ROOT + path.sep);
    if (!inScope) process.exit(0); // hors périmètre — aucun effet

    const slug = projectSlugFromCwd(resolvedCwd);
    if (!slug) process.exit(0);

    const all = JSON.parse(readFileSync(MIRROR, 'utf8'));
    // Format du miroir (vérifié le 11 juillet) : { mirrorFormatVersion, exportedAt, items: [...] }.
    const list = Array.isArray(all)
      ? all
      : Array.isArray(all.items)
        ? all.items
        : Array.isArray(all.memories)
          ? all.memories
          : [];
    // Champ de rattachement (export.Schema.ts) : `projectSlug` — référence vers
    // projects.json[].id, OMIS quand la memory n'a pas de projet.
    const candidates = list.filter(
      (m) =>
        m &&
        m.projectSlug === slug &&
        (m.scope === 'public' || m.scope === 'professionnel') &&
        typeof m.text === 'string' &&
        m.text.length > 0,
    );
    if (candidates.length === 0) process.exit(0); // pas de digest vide

    // Récence d'abord, avec bonus pour la confiance élevée et les kinds qui
    // préviennent les erreurs (leçon/décision/convention).
    const score = (m) =>
      (typeof m.confidence === 'number' && m.confidence >= 0.9 ? 1 : 0) +
      (BONUS_KINDS.has(m.kind) ? 1 : 0);
    candidates.sort((a, b) => {
      const s = score(b) - score(a);
      if (s !== 0) return s;
      return String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? ''));
    });

    const mirrorDate = (() => {
      try {
        return statSync(MIRROR).mtime.toISOString().slice(0, 10);
      } catch {
        return 'date inconnue';
      }
    })();

    const picked = candidates.slice(0, MAX_MEMORIES);
    // Assemble sous budget : le pied est fixe, la liste se tronque.
    let bullets = picked.map((m) => {
      const text = m.text.length > TEXT_TRUNC ? m.text.slice(0, TEXT_TRUNC) + '…' : m.text;
      return `- [${m.kind ?? 'memory'}] ${text}`;
    });
    const render = (bs) =>
      [
        `Mémoire du projet ${slug} — ${bs.length} entrée(s) du Second Brain (miroir du ${mirrorDate}).`,
        ...bs,
        '',
        FOOTER,
      ].join('\n');
    let digest = render(bullets);
    while (digest.length > MAX_CHARS && bullets.length > 1) {
      bullets = bullets.slice(0, -1);
      digest = render(bullets);
    }
    if (digest.length > MAX_CHARS) process.exit(0); // même 1 memory ne tient pas — silence

    process.stdout.write(
      JSON.stringify({
        hookSpecificOutput: { hookEventName: 'SessionStart', additionalContext: digest },
      }),
    );
    process.exit(0);
  });
}

main().catch(() => process.exit(0)); // fail-open : jamais casser un démarrage

