#!/usr/bin/env node
// Second Brain — digest mémoire au démarrage de session (BRIEF-19).
// Global (~/.claude/settings.json), ajouté au tableau hooks.SessionStart
// existant — jamais un remplacement des autres entrées.
//
// Trois fonctions, décidées au plan 2026-07-11-chantier-hook-sessionstart-memoire
// puis étendues le 2026-07-29 (chantier rail-application-et-boucle-lecons) :
//  1. POUSSER un digest frugal : 3-5 memories du PROJET COURANT, lues dans le
//     miroir JSON nocturne LOCAL du Second Brain (jamais Convex en direct —
//     latence + egress, leçon codifiée), scopes public/professionnel
//     uniquement, ≤ ~500 tokens.
//  2. POUSSER en plus 1-2 memories TRANSVERSES (sans projectSlug, kind
//     leçon/décision/convention, mêmes scopes) — sinon une leçon méthodologique
//     sans projet rattaché ne peut STRUCTURELLEMENT jamais atteindre une
//     session, peu importe sa pertinence (leçon vécue le 26-27/07/2026 : un
//     class-sweep re-découvert 3 fois faute d'avoir été poussé au bon moment).
//     Priorité stricte en cas de conflit de budget : les entrées PROJET
//     passent toujours avant les entrées TRANSVERSES.
//  3. APPRENDRE à la session qu'elle peut INTERROGER le brain à la demande
//     (pied d'instruction fixe) : un blocage — surtout sur un outil — a
//     peut-être déjà été résolu et payé une fois.
//
// Fiabilité avant richesse : fail-open ABSOLU (toute anomalie → exit 0
// silencieux), lecture seule stricte, aucun réseau, aucun spawn. Un hook
// mémoire qui casse un seul démarrage serait désinstallé dans la semaine.
import { homedir } from 'node:os';
import { readFileSync, statSync } from 'node:fs';
import path from 'node:path';

const SCOPE_ROOT = path.join(homedir(), 'Desktop', 'my-projets');
const MIRROR = path.join(SCOPE_ROOT, 'second-brain', 'data', 'mirror', 'json', 'memories.json');
const MAX_CHARS = 2000; // ~500 tokens — budget TOTAL (digest + pied)
const MAX_MEMORIES = 5; // plafond des entrées PROJET
const MAX_TRANSVERSE = 2; // plafond des entrées TRANSVERSES (1-2 demandé ; 2
// retenu car elles sont toujours retirées en premier en cas de dépassement de
// budget — le plafond haut ne coûte donc rien en robustesse, seulement en
// lisibilité potentielle, et 2 leçons transverses valent mieux qu'1 pour
// couvrir des classes de blocage différentes).
const TEXT_TRUNC = 280;
const BONUS_KINDS = new Set(['leçon', 'décision', 'convention']);

// Le pied d'instruction (fonction 3) — jamais tronqué : c'est la liste de
// memories qui cède la place, pas lui. Deux variantes : la version élargie
// (2026-07-29) ajoute les deux moments de consultation nommés par la leçon du
// 26-27/07/2026 (« avant le brief d'un sous-agent », « avant de déclarer un
// balayage terminé ») ; utilisée seulement si le budget le permet une fois les
// entrées (projet + transverses) posées — jamais au prix d'une entrée en moins.
const FOOTER_BASE =
  'Le Second Brain contient bien plus que ce digest. En cas de blocage — surtout ' +
  'sur un outil (CLI, MCP, daemon, harnais) — interroge-le AVANT de réessayer à ' +
  "l'aveugle : `bun run --cwd ~/Desktop/my-projets/second-brain cli/index.ts " +
  'search "<ton blocage>"` (ou `memory_search` du MCP workstation-bus) — Franck ' +
  'y a peut-être déjà payé cette erreur.';
const FOOTER_WIDE =
  'Le Second Brain contient bien plus que ce digest. Interroge-le AVANT de réessayer ' +
  'à l\'aveugle — en cas de blocage (surtout sur un outil : CLI, MCP, daemon, ' +
  'harnais), avant de rédiger le brief d\'un sous-agent, ou avant de déclarer un ' +
  "balayage terminé : `bun run --cwd ~/Desktop/my-projets/second-brain cli/index.ts " +
  'search "<ton besoin>"` (ou `memory_search` du MCP workstation-bus) — Franck y a ' +
  'peut-être déjà payé cette erreur.';

async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks).toString('utf8');
}

// Slug projet = kebab-case du premier segment sous ~/Desktop/my-projets —
// même règle déterministe que le skill brain-capture, et la forme que les
// memories du miroir utilisent réellement (workstation, second-brain, …).
function projectSlugFromCwd(resolvedCwd) {
  const rel = path.relative(SCOPE_ROOT, resolvedCwd);
  if (rel.startsWith('..') || rel === '') return null;
  const first = rel.split(path.sep)[0];
  const slug = first
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || null;
}

// Récence d'abord, avec bonus pour la confiance élevée et les kinds qui
// préviennent les erreurs (leçon/décision/convention). Partagée par les
// entrées PROJET et TRANSVERSES — un seul tri, pas de logique dupliquée.
function score(m) {
  return (
    (typeof m.confidence === 'number' && m.confidence >= 0.9 ? 1 : 0) +
    (BONUS_KINDS.has(m.kind) ? 1 : 0)
  );
}
function sortCandidates(list) {
  list.sort((a, b) => {
    const s = score(b) - score(a);
    if (s !== 0) return s;
    return String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? ''));
  });
  return list;
}

function main() {
  return readStdin().then((raw) => {
    let event;
    try {
      event = JSON.parse(raw);
    } catch {
      process.exit(0); // stdin malformé — fail-open
    }

    const cwd = typeof event.cwd === 'string' && event.cwd.length > 0 ? event.cwd : process.cwd();
    const resolvedCwd = path.resolve(cwd);
    const inScope = resolvedCwd === SCOPE_ROOT || resolvedCwd.startsWith(SCOPE_ROOT + path.sep);
    if (!inScope) process.exit(0); // hors périmètre — aucun effet

    const slug = projectSlugFromCwd(resolvedCwd);
    if (!slug) process.exit(0);

    const all = JSON.parse(readFileSync(MIRROR, 'utf8'));
    // Format du miroir (vérifié le 11 juillet) : { mirrorFormatVersion, exportedAt, items: [...] }.
    const list = Array.isArray(all)
      ? all
      : Array.isArray(all.items)
        ? all.items
        : Array.isArray(all.memories)
          ? all.memories
          : [];
    // Champ de rattachement (export.Schema.ts) : `projectSlug` — référence vers
    // projects.json[].id, OMIS quand la memory n'a pas de projet.
    const projectCandidates = list.filter(
      (m) =>
        m &&
        m.projectSlug === slug &&
        (m.scope === 'public' || m.scope === 'professionnel') &&
        typeof m.text === 'string' &&
        m.text.length > 0,
    );
    // Candidats TRANSVERSES : aucun projectSlug (pas de comparaison stricte à
    // `slug` — `!m.projectSlug` couvre absent/null/vide), et seulement les
    // kinds déjà bonifiés (leçon/décision/convention) — pas n'importe quel
    // kind, pour rester des rappels méthodologiques et non du bruit factuel.
    const transverseCandidates = list.filter(
      (m) =>
        m &&
        !m.projectSlug &&
        BONUS_KINDS.has(m.kind) &&
        (m.scope === 'public' || m.scope === 'professionnel') &&
        typeof m.text === 'string' &&
        m.text.length > 0,
    );
    if (projectCandidates.length === 0 && transverseCandidates.length === 0) {
      process.exit(0); // pas de digest vide
    }

    sortCandidates(projectCandidates);
    sortCandidates(transverseCandidates);

    const mirrorDate = (() => {
      try {
        return statSync(MIRROR).mtime.toISOString().slice(0, 10);
      } catch {
        return 'date inconnue';
      }
    })();

    const fmt = (m) => (m.text.length > TEXT_TRUNC ? m.text.slice(0, TEXT_TRUNC) + '…' : m.text);

    // Entrées PROJET — format inchangé.
    let projectBullets = projectCandidates
      .slice(0, MAX_MEMORIES)
      .map((m) => `- [${m.kind ?? 'memory'}] ${fmt(m)}`);
    // Entrées TRANSVERSES — préfixe distinct pour que le lecteur (humain ou la
    // session elle-même) sache d'où vient chaque ligne sans ambiguïté.
    let transverseBullets = transverseCandidates
      .slice(0, MAX_TRANSVERSE)
      .map((m) => `- [transverse:${m.kind}] ${fmt(m)}`);

    const render = (pBullets, tBullets, footer) => {
      const parts = [];
      if (pBullets.length > 0) {
        parts.push(
          `Mémoire du projet ${slug} — ${pBullets.length} entrée(s) du Second Brain (miroir du ${mirrorDate}).`,
          ...pBullets,
        );
      }
      if (tBullets.length > 0) {
        if (parts.length > 0) parts.push('');
        parts.push(
          `Mémoire transverse (sans projet) — ${tBullets.length} entrée(s) du Second Brain (miroir du ${mirrorDate}).`,
          ...tBullets,
        );
      }
      parts.push('', footer);
      return parts.join('\n');
    };

    let digest = render(projectBullets, transverseBullets, FOOTER_BASE);
    // Troncature sous budget : le pied est fixe, la liste cède la place — et
    // les entrées TRANSVERSES cèdent AVANT les entrées PROJET (priorité aux
    // entrées projet en cas de conflit d'espace).
    while (digest.length > MAX_CHARS && projectBullets.length + transverseBullets.length > 1) {
      if (transverseBullets.length > 0) {
        transverseBullets = transverseBullets.slice(0, -1);
      } else {
        projectBullets = projectBullets.slice(0, -1);
      }
      digest = render(projectBullets, transverseBullets, FOOTER_BASE);
    }
    if (digest.length > MAX_CHARS) process.exit(0); // même 1 entrée ne tient pas — silence

    // Pied élargi (2026-07-29) : seulement si ça tient SANS retoucher aux
    // entrées déjà retenues — jamais au prix d'une memory en moins.
    const wide = render(projectBullets, transverseBullets, FOOTER_WIDE);
    if (wide.length <= MAX_CHARS) digest = wide;

    process.stdout.write(
      JSON.stringify({
        hookSpecificOutput: { hookEventName: 'SessionStart', additionalContext: digest },
      }),
    );
    process.exit(0);
  });
}

main().catch(() => process.exit(0)); // fail-open : jamais casser un démarrage

