  "kind": "decision",
  "allowMultiple": false,
  "allowCustom": true,
  "options": [
    {
      "id": "opt-second-brain-seul",
      "label": "(a) Second Brain seul",
      "description": "Aucun nouvel outillage. Insuffisant à lui seul d'après la leçon du 2026-07-26 — un chantier de Franck sur ce sujet est déjà en cours côté second-brain."
    },
    {
      "id": "opt-meta-govern-lifecycle",
      "label": "(b) Lesson lifecycle de meta-govern",
      "description": "Doctrine déjà écrite (governance-cadence.html, lessons-log.html) : règle textuelle → scopée par chemin → hook ombre → hook bloquant → test.",
      "recommended": true
