      const { fromJobs, jobsSummary } = deriveImprovementDiffJustification(skill, itemKey, ctx?.siblingResults);

      const applyCtx: ApplyContext = applyContextFromEnv();
      // `resolveCurrentMainShaForSkill` lève une erreur claire (« ApplyContext
