      // le cas actuel de cette machine (`bun run evals rail-doctor` rend
      // NOT_WIRED aujourd'hui).
      const beforeSha = await resolveCurrentMainShaForSkill(skill, applyCtx);

      const destinationRemote = skill === 'meta-govern' ? applyCtx.metaGovernRepo?.remote : applyCtx.skillRepo?.remote;
      if (!destinationRemote) {
        // Ne devrait pas arriver : `resolveCurrentMainShaForSkill` ci-dessus
