      // même skill/nightDate/version(1) que ce que `saveGateConversation`
      // calculera en interne pour la VRAIE proposal (apply.ts,
      // `proposalBranchName`, § NIGHTDATE OVERRIDE) puisque le MÊME
      // `nightDate` est passé aux deux.
      const branch = proposalBranchName(
        { skill, id: 'n/a', version: 1, updatedAt: new Date().toISOString() },
        nightDate,
      );

      const transportResult = await transportImproveBranch({
        cargoRemote: cargoRemoteUrl(),
        destinationRemote,
        branch,
      });
      if (!transportResult.ok) {
        throw new Error(
          `transport cargo -> skills en échec (${transportResult.kind}) pour la branche ${branch} : ${transportResult.reason}`,
        );
      }

      // Synthèse locale, PAS un vrai diff unifié : le cloud ne fournit qu'une
      // liste de chemins + une note pour un `improvementDiff` (voir
      // docs/evals/results-contract.md) — l'import ne parse aucun diff.
      const diffText = buildImprovementDiffSummaryText(r);
      const { diffPath, backupPath } = await writeImprovementDiffArtifacts(skill, nightDate, diffText);

      await createGatedProposal({
        skill,
        fromJobs,
        beforeSha,
        diffPath,
        backupPath,
        jobsSummary,
        diffText,
        expectedEffect:
          "Effet non mesuré à l'import — à évaluer après application via le prochain cycle de jobs notés.",
