      // NOMME la cause de l'échec (transport, rail non câblé, proposal déjà
      // 'proposed' pour ce skill, …) au lieu du texte générique d'avant ce
      // lot. Ne pose jamais de `response` sur quoi que ce soit — ce chemin ne
      // touche à aucune gate (l'échec survient avant ou pendant
      // `createGatedProposal`, jamais après).
      const detail =
        err instanceof DuplicateProposedProposalError
          ? `une proposal 'proposed' existe déjà pour ce skill (${err.existingProposalId}) — enrichir fromJobs plutôt que d'en créer une seconde`
          : (err as Error).message;
      await createChipFromInput({
        title: `Correctif candidat — ${skillLabel}`,
        prompt:
          `Le round cloud a proposé un correctif pour le skill "${skillLabel}" (résultat d'import evals, banc d'essai). ` +
          `La création automatique de la gate d'approbation + ImprovementProposal a ÉCHOUÉ : ${detail} ` +
          '(voir « bun run evals rail-doctor » si la cause est un rail non câblé). ' +
          `Chemins modifiés : ${(r.changedPaths ?? []).join(', ') || '(aucun)'}. Note : ${r.note ?? '(aucune)'}.`,
        tldr: `Repli en chip — création automatique de gate/proposal échouée pour "${skillLabel}" (${detail}).`,
        cwd: root(),
        source: 'cli',
      });
      return;
    }
  }

  // kind === 'note' (or an unrecognised jobId/sessionId-less shape) — nothing
