export async function listImprovementProposals(filter?: {
  skill?: string;
  state?: ImprovementProposalState[];
}): Promise<ImprovementProposal[]> {
  let proposals = await listDirEntities(improvementsDir(), ImprovementProposalSchema);
  if (filter?.skill) proposals = proposals.filter((p) => p.skill === filter.skill);
  if (filter?.state) {
    const states = new Set(filter.state);
    proposals = proposals.filter((p) => states.has(p.state));
  }
  return proposals;
}

