      branch,
    });
    if (!transportResult.ok) {
      throw new Error(
        `transport cargo -> skills en échec (${transportResult.kind}) pour la branche ${branch} : ${transportResult.reason}`,
      );
    }
    // Posé UNIQUEMENT une fois le push réellement effectué (ou constaté
    // déjà à jour) — c'est ce qui distingue "rien n'a mutation le dépôt
    // réel" de "une branche existe désormais sur le dépôt réel", pour le
    // repli en chip plus bas.
    transportedBranch = branch;

    // Synthèse locale, PAS un vrai diff unifié : le cloud ne fournit qu'une
    // liste de chemins + une note pour un `improvementDiff` (voir
    // docs/evals/results-contract.md) — l'import ne parse aucun diff.
    const diffText = buildImprovementDiffSummaryText(r);
    const artifacts = await writeImprovementDiffArtifacts(skill, nightDate, diffText);
    writtenArtifacts = artifacts;

    await createGatedProposal({
      skill,
      fromJobs,
      beforeSha,
      diffPath: artifacts.diffPath,
      backupPath: artifacts.backupPath,
      jobsSummary,
      diffText,
      expectedEffect:
        "Effet non mesuré à l'import — à évaluer après application via le prochain cycle de jobs notés.",
      nightDate,
    });
    return;
  } catch (err) {
    // Nettoyage best-effort des artefacts diff/backup ÉCRITS par CETTE
    // tentative avant l'échec (revue adversariale round 1, state-safety,
    // P3) — jamais bloquant : un `rm` qui échoue à son tour ne doit pas
    // masquer l'erreur d'origine ni empêcher la création du chip
    // ci-dessous. Suit le même idiome que le nettoyage best-effort déjà en
    // place dans apply.ts (`fs.rm(..., { force: true }).catch(() => {})`).
    if (writtenArtifacts) {
      await rm(writtenArtifacts.diffPath, { force: true }).catch(() => {});
      await rm(writtenArtifacts.backupPath, { force: true }).catch(() => {});
    }

    // Repli obligatoire : filet de sécurité — un correctif proposé par le
    // cloud ne doit JAMAIS disparaître silencieusement. Le prompt du chip
    // NOMME la cause de l'échec (transport, rail non câblé, proposal déjà
    // 'proposed' pour ce skill, …). Ne pose jamais de `response` sur quoi
    // que ce soit. NOTE (corrigée après revue adversariale) : ce chemin
    // PEUT avoir déjà poussé une branche réelle sur le dépôt de skills
    // (`transportedBranch`) avant l'échec — le pré-check mono-proposal
    // ci-dessus élimine le cas ORDINAIRE, mais un échec plus tardif
    // (transport résolu puis `createGatedProposal` qui échoue pour une
    // autre raison, ex. write transitoire) reste possible ; le nommer dans
    // le chip est ce qui permet à un humain de la retrouver/réutiliser.
    const detail =
      err instanceof DuplicateProposedProposalError
        ? `une proposal 'proposed' existe déjà pour ce skill (${err.existingProposalId}) — enrichir fromJobs plutôt que d'en créer une seconde`
        : (err as Error).message;
    const branchNote = transportedBranch
      ? ` Une branche ${transportedBranch} a déjà été poussée sur le dépôt de skills réel avant cet échec — vérifier son état avant de relancer.`
      : '';
    await createChipFromInput({
      title: `Correctif candidat — ${skillLabel}`,
      prompt:
        `Le round cloud a proposé un correctif pour le skill "${skillLabel}" (résultat d'import evals, banc d'essai). ` +
        `La création automatique de la gate d'approbation + ImprovementProposal a ÉCHOUÉ : ${detail}.` +
        branchNote +
        ' (voir « bun run evals rail-doctor » si la cause est un rail non câblé). ' +
        `Chemins modifiés : ${(r.changedPaths ?? []).join(', ') || '(aucun)'}. Note : ${r.note ?? '(aucune)'}.`,
      tldr: `Repli en chip — création automatique de gate/proposal échouée pour "${skillLabel}" (${detail}).`,
      cwd: root(),
      source: 'cli',
    });
    // Repropagé (revue adversariale round 1, wiring, P2) : le chip est un
    // filet de sécurité pour NE PAS PERDRE le correctif, pas une absorption
    // silencieuse de l'échec lui-même — sans ce throw, l'appelant
    // (`cmdImport`) ne voyait jamais cet échec, l'item était compté
    // « ingéré » comme un succès normal, et `gaps`/VERDICT ne le
    // signalaient jamais (Fix #6, plus bas, ne s'applique qu'aux erreurs
    // qui remontent jusqu'à lui). Rethrow ici fait rentrer ce cas dans la
    // MÊME escalade que tout autre side-effect en échec.
    throw err;
  }
}

