test('improvementDiff valide (chemins dans le dossier du skill), rail NON câblé -> repli en chip (cause nommée)', async () => {
  await importStore();
  const root = await freshRoot();
  const bareDir = await initBareRepo();
  const date = todayUtcDate();
  const results = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    results: [
      {
        kind: 'improvementDiff',
        skill: 'valid-scope-skill',
        changedPaths: ['valid-scope-skill/SKILL.md'],
      },
    ],
  };
  await pushBranch(bareDir, `results/${date}`, { 'results.json': JSON.stringify(results, null, 2) });

  // AUCUNE variable WORKSTATION_SKILLS_*/WORKSTATION_METAGOVERN_* posée —
  // rail NOT_WIRED (voir `bun run evals rail-doctor`), le cas actuel de
  // cette machine : `applyResultSideEffects` doit retomber sur le MÊME
  // repli en chip qu'avant ce lot (item quand même compté "ingéré", aucun
  // écart), mais avec un prompt qui NOMME désormais la cause de l'échec.
  const { stdout } = await run(root, ['import', '--from', bareDir]);
  expect(stdout).not.toContain('REJETÉ');
  expect(stdout).toContain('ingéré');

  const chips = await chipStore.listChips();
  const chipMeta = chips.find((c) => c.title.includes('valid-scope-skill'));
  expect(chipMeta).toBeDefined();
  const chip = await chipStore.findChip(chipMeta!.id);
  expect(chip?.prompt).toContain('ApplyContext.skillRepo manquant');
  expect(chip?.prompt).toContain('rail-doctor');

