test('improvementDiff, rail CÂBLÉ, proposal DÉJÀ proposed pour ce skill -> repli en chip SANS créer une seconde gate orpheline (revue adversariale round 1)', async () => {
  // Reproduit le défaut P1 trouvé en revue adversariale : avant le
  // pré-check mono-proposal, une deuxième nuit visant un skill dont la
  // proposal de la nuit précédente est encore 'proposed' poussait quand
  // même une branche réelle ET écrivait une gate 'approval' réelle AVANT
  // d'échouer sur DuplicateProposedProposalError — laissant une gate
  // orpheline pour toujours dans le hub. Ce test prouve que le pré-check
  // court-circuite AVANT toute mutation de ce genre.
  await importStore();
  const root = await freshRoot();
  const skill = 'rail-wired-skill-dup';
  const cargoBare = await initBareRepo();
  const skillsBare = await initBareRepo();
  const fxRoot = await mkdtemp(path.join(os.tmpdir(), 'wsevalsrec-railwired-dup-'));
  tmpRoots.push(fxRoot);

  await pushBranch(skillsBare, 'main', { [`${skill}/SKILL.md`]: 'v1 — avant correctif\n' });

  const extraEnv = {
    CARGO_REMOTE_URL: cargoBare,
    WORKSTATION_SKILLS_REPO_REMOTE: skillsBare,
    WORKSTATION_SKILLS_INTEGRATION_CLONE: path.join(fxRoot, 'ic'),
    WORKSTATION_SKILLS_INSTALL_ROOT: path.join(fxRoot, 'install-root'),
  };

  // Nuit 1 — import réussi, proposal reste 'proposed' (jamais approuvée).
  const date1 = '2026-07-27';
  const branch1 = `improve/${skill}-${date1}`;
  await pushBranch(cargoBare, branch1, { [`${skill}/SKILL.md`]: 'v2 — nuit 1\n' });
  await pushBranch(cargoBare, `results/${date1}`, {
    'results.json': JSON.stringify(
      {
        schemaVersion: 1,
        generatedAt: new Date().toISOString(),
        results: [{ kind: 'improvementDiff', skill, changedPaths: [`${skill}/SKILL.md`], note: 'nuit 1' }],
      },
      null,
      2,
    ),
  });
  const first = await run(root, ['import', '--from', cargoBare, '--date', date1], extraEnv);
  expect(first.stdout).toContain('ingéré');

  const proposalsAfterFirst = await store.listImprovementProposals({ skill, state: ['proposed'] });
  expect(proposalsAfterFirst.length).toBe(1);

  // Nuit 2 — même skill, proposal de la nuit 1 toujours 'proposed'.
  const date2 = '2026-07-28';
  const branch2 = `improve/${skill}-${date2}`;
  await pushBranch(cargoBare, branch2, { [`${skill}/SKILL.md`]: 'v3 — nuit 2\n' });
  await pushBranch(cargoBare, `results/${date2}`, {
    'results.json': JSON.stringify(
      {
        schemaVersion: 1,
        generatedAt: new Date().toISOString(),
        results: [{ kind: 'improvementDiff', skill, changedPaths: [`${skill}/SKILL.md`], note: 'nuit 2' }],
      },
      null,
      2,
    ),
  });
  const second = await run(root, ['import', '--from', cargoBare, '--date', date2], extraEnv);
  expect(second.stdout).toContain('VERDICT: IMPORTED_WITH_GAPS');

  // Toujours UNE SEULE proposal 'proposed' pour ce skill — pas de v2 créée.
  const proposalsAfterSecond = await store.listImprovementProposals({ skill, state: ['proposed'] });
  expect(proposalsAfterSecond.length).toBe(1);
  expect(proposalsAfterSecond[0].id).toBe(proposalsAfterFirst[0].id);

  // Un chip nomme la cause exacte.
  const chips = await chipStore.listChips();
  const chip = chips.find((c) => c.title.includes(skill));
  expect(chip).toBeDefined();
  const chipFull = await chipStore.findChip(chip!.id);
  expect(chipFull?.prompt).toContain("proposal 'proposed' existe déjà");

  // LA preuve du fix : exactement UNE gate 'approval' pour ce skill dans le
  // hub — la nuit 2 n'a jamais durablement écrit de seconde conversation
  // avant d'échouer (le pré-check l'a empêché AVANT tout appel à
  // transportImproveBranch/createGatedProposal).
  const workstationConvos = await conversationStore.listConversations('workstation');
  const gatesForSkill = workstationConvos.filter((c) => c.id.includes(`gate-${skill}`));
  expect(gatesForSkill.length).toBe(1);

  // La branche de la nuit 2 n'a JAMAIS été poussée sur la destination —
  // le pré-check court-circuite avant tout appel à transportImproveBranch.
  const destBranch2Sha = execFileSync(
    'git',
    ['ls-remote', '--heads', skillsBare, branch2],
    { encoding: 'utf8' },
  ).trim();
  expect(destBranch2Sha.length).toBe(0);
});

