export const meta = {
  name: 'pr-adversarial-review-round2-fix',
  description: 'Re-verify the round-1 fix for the improvementDiff orphan-gate defect',
  phases: [{ title: 'Hunt' }, { title: 'Verify' }],
}

const REPO = '/Users/elmabi/Desktop/my-projets/workstation'
const CONTEXT = `Adversarially review the CURRENT diff at ${REPO} between base branch "main" and HEAD (branch chantier/rail-application-et-boucle-lecons) — this is ROUND 2, after round 1 fixed a confirmed P1 state-safety defect.
Run \`git -C ${REPO} diff main...HEAD -- server/cli/evalsReconciler.ts server/cli/evals.ts docs/decision-hub.md server/cli/evalsReconciler.test.ts server/cli/evals.test.ts\` and read the full changed regions + their callers.
ROUND 1 FIX SUMMARY (verify this actually closes the defects, does not regress anything, and does not introduce a NEW defect):
- server/cli/evalsReconciler.ts: applyResultSideEffects's improvementDiff branch now pre-checks listImprovementProposals({skill, state:['proposed']}) BEFORE calling transportImproveBranch/writeImprovementDiffArtifacts/createGatedProposal, throwing DuplicateProposedProposalError early if a 'proposed' proposal already exists — so no git push, no artifact write, and no gate conversation write happens in that case. transportedBranch/writtenArtifacts are tracked and used for (a) best-effort cleanup (rm) of orphan artifact files on ANY failure, (b) naming the already-pushed branch in the fallback chip prompt when the failure happens after a successful transport. The catch block now RETHROWS after creating the fallback chip (previously it returned normally), so the failure is now routed through cmdImport's existing 'gaps' escalation (Fix #6) and VERDICT becomes IMPORTED_WITH_GAPS instead of a silent IMPORTED.
- server/cli/evals.ts: cmdLessons now validates --since against /^\\d{4}-\\d{2}-\\d{2}$/ before calling aggregateLessons, calling fail() on a malformed value.
- docs/decision-hub.md: updated to document both VERDICT: COMPLETED and VERDICT: FOLLOWUP_PENDING as exit-0 outcomes of convo watch.
- Two test files updated/added accordingly (a new regression test for the duplicate-proposal pre-check, verifying exactly one gate conversation exists and the second branch was never pushed).
A finding is reportable if it fails ANY gate: CORRECTNESS (wrong output/crash/lose data), CONVENTION/SCALABILITY/PLATFORM-LIMIT (deviates from a cited repo idiom or external limit, even if it works today), WIRING (new/changed code not reachable/registered correctly, or a doc/comment asserting behavior the code doesn't have), STATE-SAFETY (a gate/proposal path that can still leak orphan state, lose a proposed correctif, or corrupt state on a failure path). "Not triggerable today" is NOT grounds to drop a Gate-B finding. Refute ONLY pure style.
Focus especially on: (1) does the pre-check + rethrow introduce a NEW state-safety gap (e.g. does rethrowing after chip creation risk the chip itself being duplicated on a hypothetical retry, given the marker-write-before-side-effect ordering)? (2) is there still ANY path where saveGateConversation's write can happen before a failure that isn't now caught by the pre-check (e.g. a race between the pre-check read and the actual createGatedProposal call, given cmdImport holds an 'import' lock for the whole run — confirm whether concurrent evals apply/revert could still interleave)? (3) does the best-effort artifact cleanup ever mask a MORE important error, or could it throw and swallow the original error? (4) is the new evalsReconciler.test.ts regression test actually asserting what it claims (read it fully)?`

const FINDINGS = { type:'object', additionalProperties:false, required:['findings'], properties:{ findings:{ type:'array', items:{
  type:'object', additionalProperties:false,
  required:['title','file','line','class','severity','scenario','suggestedFix'],
  properties:{ title:{type:'string'}, file:{type:'string'}, line:{type:'string'},
    class:{type:'string', enum:['correctness','convention','scalability','platform-limit','wiring','state-safety']},
    severity:{type:'string', enum:['P1','P2','P3']}, scenario:{type:'string'}, suggestedFix:{type:'string'} } } } } }

const VERDICT = { type:'object', additionalProperties:false,
  required:['mustFix','class','reasoning'],
  properties:{ mustFix:{type:'boolean'},
    class:{type:'string', enum:['correctness','convention','scalability','platform-limit','wiring','state-safety','style']},
    repoIdiomViolated:{type:'string'},
    confidence:{type:'string',enum:['high','medium','low']}, reasoning:{type:'string'} } }

const DIMENSIONS = [
  { key:'state-safety',  focus:'Does the round-1 fix actually close the orphan-gate/orphan-branch/orphan-artifact defect for the common case, and does the rethrow + marker-already-written interaction risk any double-chip-creation or lost-item scenario on a retry?' },
  { key:'correctness',   focus:'Logic bugs in the new pre-check/cleanup/rethrow code: off-by-one, wrong condition, a throw inside the catch block that could mask the original error, an await ordering bug.' },
  { key:'contracts',     focus:'Does the rethrow change break any OTHER caller/consumer of applyResultSideEffects or cmdImport that assumed improvementDiff never throws? Check the two judge-local replay call sites and cmdImport error handling paths.' },
]

phase('Hunt')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(`${CONTEXT}\n\nDIMENSION: ${d.focus}`, { label:`hunt:${d.key}`, phase:'Hunt', schema:FINDINGS, effort:'high' }),
  (review) => parallel((review?.findings ?? []).map((f) => () =>
    agent(`${CONTEXT}\n\nADVERSARIALLY VERIFY this finding. Set mustFix TRUE only if the facts hold against the real code and it's a genuine correctness/state-safety/contract regression or an unresolved instance of the original defect class. Set FALSE if the facts don't hold or it's pure style.\n\n${JSON.stringify(f,null,2)}`,
      { label:`verify:${f.file}:${f.line}`, phase:'Verify', schema:VERDICT, effort:'high' })
      .then((v) => ({ finding:f, verdict:v }))))
)
const confirmed = results.flat().filter(Boolean).filter((r) => r?.verdict?.mustFix)
return { verdict: confirmed.length ? 'FINDINGS' : 'PASS', confirmed: confirmed.map((r) => ({ ...r.finding, verdict:r.verdict })) }

