function improvementDiffArtifactPaths(skill: string, nightDate: string): { diffPath: string; backupPath: string } {
  const base = `${slugify(skill)}-${nightDate}`;
  return {
    diffPath: path.join(reviewsDir(), 'proposals', `${base}.diff`),
    backupPath: path.join(reviewsDir(), 'proposals', `${base}.backup-placeholder`),
  };
}

async function writeImprovementDiffArtifacts(
  diffPath: string,
  backupPath: string,
  diffText: string,
): Promise<void> {
  await atomicWrite(diffPath, diffText);
  await atomicWrite(
    backupPath,
    'placeholder — aucun contenu de backup à la création de la gate ; apply.ts ne lit jamais ce fichier, ' +
      "c'est une trace informative pour un futur lecteur humain\n",
  );
}

