test('nightDate override — Montréal UTC-4 : la branche reste datée de la nuit, pas de l\'horloge UTC', async () => {
  await freshRoot();
  const skill = 'timezone-skill';

  // Simule un import lancé à 20h00 locales le 29 juillet à Montréal
