    const { branch } = await applyMod.createGatedProposal(
      baseGateInput({ skill, beforeSha: 'deadbeef', nightDate: '2026-07-29' }),
    );
    expect(branch).toBe(`improve/${skill}-2026-07-29`);
  } finally {
    spy.mockRestore();
  }
});

