test('createGatedProposal auto-nettoie sa propre gate si createImprovementProposal échoue (revue adversariale round 2, state-safety)', async () => {
  // Reproduit le défaut trouvé en round 2 : createGatedProposal écrit
  // TOUJOURS la conversation approval en premier (saveGateConversation),
  // puis createImprovementProposal peut lever DuplicateProposedProposalError
  // (mono-proposal invariant) — sans nettoyage, cette gate reste orpheline
  // pour toujours (aucune ImprovementProposal ne référence jamais un
  // gateRef qui n'a pas été créé). Un second appel pour le MÊME skill,
  // pendant que le premier reste 'proposed', est le moyen le plus direct de
  // déclencher ce chemin de façon déterministe (pas besoin de simuler la
  // course entre deux verrous distincts pour prouver l'auto-nettoyage).
  await freshRoot();
  const skill = 'self-cleaning-gate-skill';

  const first = await applyMod.createGatedProposal(baseGateInput({ skill, beforeSha: 'deadbeef' }));
  const firstConv = await conversationStore.getConversation(
    ...(first.gateRef.split('/') as [string, string]),
  );
  expect(firstConv).not.toBeNull();

  let secondGateRef: string | undefined;
  try {
    await applyMod.createGatedProposal(baseGateInput({ skill, beforeSha: 'deadbeef' }));
    throw new Error('devait lever DuplicateProposedProposalError');
  } catch (err) {
    expect((err as Error).message).toMatch(/proposed.*existe déjà|already exists|proposed'/i);
    // Le gateRef de la tentative échouée n'est jamais retourné à l'appelant
    // (createGatedProposal a levé avant son `return`) — on le retrouve donc
    // en listant les conversations du projet hub et en écartant celle du
    // premier appel, pour vérifier qu'elle a bien été nettoyée.
    const allGates = await conversationStore.listConversations('workstation');
    const candidateSecond = allGates.find(
      (c) => c.id.includes(`gate-${skill}`) && c.id !== first.gateRef.split('/')[1],
    );
    secondGateRef = candidateSecond?.id;
  }

  // La gate du PREMIER appel (réussi) reste intacte.
  const firstConvAfter = await conversationStore.getConversation(
    ...(first.gateRef.split('/') as [string, string]),
  );
  expect(firstConvAfter).not.toBeNull();

  // La gate du SECOND appel (échoué) ne doit PLUS être lisible — c'est la
  // preuve de l'auto-nettoyage : `listConversations` ne doit trouver AUCUNE
  // seconde gate pour ce skill (elle n'existe plus sous data/conversations/,
  // déplacée vers data/trash/ par `deleteConversation`).
  expect(secondGateRef).toBeUndefined();

  // Une seule ImprovementProposal 'proposed' pour ce skill — pas de v2.
  const proposals = await store.listImprovementProposals({ skill, state: ['proposed'] });
  expect(proposals.length).toBe(1);
  expect(proposals[0].id).toBe(first.proposal.id);
});

