export const meta = {
  name: 'pr-adversarial-review-round3-fix',
  description: 'Final targeted re-verification of the self-cleaning gate fix',
  phases: [{ title: 'Hunt' }, { title: 'Verify' }],
}

const REPO = '/Users/elmabi/Desktop/my-projets/workstation'
const CONTEXT = `Adversarially review the CURRENT diff at ${REPO} between base branch "main" and HEAD (branch chantier/rail-application-et-boucle-lecons) — this is ROUND 3, the final targeted check.
Run \`git -C ${REPO} diff main...HEAD -- server/services/reviews/apply.ts server/cli/evalsReconciler.ts\` and read the two changed regions in full plus their callers.
ROUND 2 FIX being verified in THIS round:
- server/services/reviews/apply.ts's createGatedProposal now wraps its createImprovementProposal call in try/catch: on ANY failure, it best-effort calls deleteConversation(gateSlug, gateId) on the gate conversation saveGateConversation just wrote (moves it to trash, never throws itself — .catch(()=>{})), then rethrows the original error. This is meant to make createGatedProposal self-contained/transactional regardless of which caller races with which other one (evalsReconciler.ts's improvementDiff branch is its only production caller; superviseChangesRequested calls saveGateConversation directly, NOT through createGatedProposal, so it is unaffected).
- server/cli/evalsReconciler.ts: writeImprovementDiffArtifacts was split into a pure improvementDiffArtifactPaths(skill, nightDate) path-computation helper plus a writeImprovementDiffArtifacts(diffPath, backupPath, diffText) writer; applyResultSideEffects now computes the paths and sets writtenArtifacts = artifacts BEFORE calling the writer, so best-effort cleanup (rm force:true) covers a partial-write failure (diffPath written, backupPath write fails) too.
A finding is reportable if it fails ANY gate: CORRECTNESS, CONVENTION/SCALABILITY/PLATFORM-LIMIT, WIRING, STATE-SAFETY (still-orphaned or newly-introduced partial/corrupt state on any failure path). "Not triggerable today" is NOT grounds to drop a Gate-B finding. Refute ONLY pure style.
Specifically verify: (1) does deleteConversation's own failure mode (e.g. permission error, cross-device rename issue) ever propagate and mask the ORIGINAL createImprovementProposal error, given the .catch(()=>{})? (2) is there any remaining path where saveGateConversation's write survives a createGatedProposal failure — e.g. does the new try/catch actually wrap the ENTIRE createImprovementProposal call, or could an error thrown by something else (unlikely but check) escape uncaught? (3) does deleteConversation's move-to-trash (not hard delete) create any NEW problem — e.g. could a NEXT createGatedProposal call for the same skill/gateId collide with the trashed file, or does gateId's crypto.randomBytes suffix make collision impossible? (4) is the new apply.test.ts test for this ('createGatedProposal auto-nettoie...') actually testing what it claims, and does it correctly distinguish the first (surviving) gate from the second (cleaned-up) one? (5) any regression in the artifact-path split — does the caller still pass the SAME diffPath/backupPath into createGatedProposal that were computed/written, with no mismatch?`

const FINDINGS = { type:'object', additionalProperties:false, required:['findings'], properties:{ findings:{ type:'array', items:{
  type:'object', additionalProperties:false,
  required:['title','file','line','class','severity','scenario','suggestedFix'],
  properties:{ title:{type:'string'}, file:{type:'string'}, line:{type:'string'},
    class:{type:'string', enum:['correctness','convention','scalability','platform-limit','wiring','state-safety']},
    severity:{type:'string', enum:['P1','P2','P3']}, scenario:{type:'string'}, suggestedFix:{type:'string'} } } } } }

const VERDICT = { type:'object', additionalProperties:false,
  required:['mustFix','class','reasoning'],
  properties:{ mustFix:{type:'boolean'},
    class:{type:'string', enum:['correctness','convention','scalability','platform-limit','wiring','state-safety','style']},
    repoIdiomViolated:{type:'string'},
    confidence:{type:'string',enum:['high','medium','low']}, reasoning:{type:'string'} } }

const DIMENSIONS = [
  { key:'state-safety', focus:'Does the self-cleaning fix in createGatedProposal fully close the orphan-gate defect class for its actual call site, or does it introduce a new failure mode of its own?' },
  { key:'correctness',  focus:'Logic bugs in the try/catch, the gateRef.split, the artifact-path split — verify against the real code.' },
]

phase('Hunt')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(`${CONTEXT}\n\nDIMENSION: ${d.focus}`, { label:`hunt:${d.key}`, phase:'Hunt', schema:FINDINGS, effort:'high' }),
  (review) => parallel((review?.findings ?? []).map((f) => () =>
    agent(`${CONTEXT}\n\nADVERSARIALLY VERIFY this finding. Set mustFix TRUE only if the facts hold against the real code and it's a genuine unresolved defect. Set FALSE if facts don't hold or it's pure style.\n\n${JSON.stringify(f,null,2)}`,
      { label:`verify:${f.file}:${f.line}`, phase:'Verify', schema:VERDICT, effort:'high' })
      .then((v) => ({ finding:f, verdict:v }))))
)
const confirmed = results.flat().filter(Boolean).filter((r) => r?.verdict?.mustFix)
return { verdict: confirmed.length ? 'FINDINGS' : 'PASS', confirmed: confirmed.map((r) => ({ ...r.finding, verdict:r.verdict })) }

